def default_ops_root() -> Path:
    ops_root = CLUTCH_HOME / "ops" / "current"
    if ops_root.exists():
        return ops_root
    return ROOT_DIR


def registry_path(ops_root: Path, filename: str) -> Path:
    ops_candidate = ops_root / "registry" / filename
    if ops_candidate.exists():
        return ops_candidate
    return ROOT_DIR / "registry" / filename


def load_registry_payload(ops_root: Path, filename: str) -> dict[str, Any]:
    payload = load_json(registry_path(ops_root, filename), {})
    return payload if isinstance(payload, dict) else {}


def save_registry_payload(ops_root: Path, filename: str, payload: dict[str, Any]) -> None:
    save_json(registry_path(ops_root, filename), payload)


def load_registry(ops_root: Path, filename: str, key: str) -> list[dict[str, Any]]:
    payload = load_registry_payload(ops_root, filename)
    items = payload.get(key, [])
    return items if isinstance(items, list) else []


def load_machine_profile() -> dict[str, Any]:
    return load_json(LOCAL_PROFILE_PATH, {})


def deep_merge_dict(base: dict[str, Any], override: dict[str, Any]) -> dict[str, Any]:
    merged = json.loads(json.dumps(base))
    for key, value in override.items():
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key] = deep_merge_dict(merged[key], value)
        else:
            merged[key] = value
    return merged


def load_machine_settings() -> dict[str, Any]:
    payload = load_json(MACHINE_SETTINGS_PATH, {})
    if not isinstance(payload, dict):
        payload = {}
    return deep_merge_dict(default_machine_settings(), payload)


def save_machine_settings(payload: dict[str, Any]) -> None:
    save_json(MACHINE_SETTINGS_PATH, payload)


def machine_connection_state(settings: dict[str, Any] | None = None) -> dict[str, Any]:
    payload = settings or load_machine_settings()
    value = payload.get("machine_connection", {})
    if not isinstance(value, dict):
        value = {}
    merged = {
        "attached": True,
        "detach_reason": "",
        "last_detach_time_ns": 0,
        "last_reconnect_time_ns": 0,
    }
    merged.update(value)
    return merged


def local_projects_root(machine_settings: dict[str, Any] | None = None) -> Path:
    settings = machine_settings or load_machine_settings()
    local_customization = (
        settings.get("local_customization", {})
        if isinstance(settings.get("local_customization"), dict)
        else {}
    )
    configured = str(local_customization.get("projects_root") or "").strip()
    if configured:
        return Path(configured).expanduser()
    return LOCAL_PROJECTS_ROOT


