def project_operator_intents_dir(local_files: dict[str, Any]) -> Path:
    explicit = str(local_files.get("operator_intents_dir") or "").strip()
    if explicit:
        return Path(explicit).expanduser()
    project_root = Path(str(local_files.get("project_root") or "")).expanduser()
    return project_root / OPERATOR_INTENT_DIRNAME


def operator_intent_status(intent: dict[str, Any]) -> str:
    status = str(intent.get("status") or "pending").strip() or "pending"
    expires_at = str(intent.get("expires_at_local") or "").strip()
    if status in OPERATOR_INTENT_PENDING_STATUSES and expires_at:
        try:
            expires_dt = datetime.fromisoformat(expires_at)
            now_dt = datetime.now(expires_dt.tzinfo) if expires_dt.tzinfo else datetime.now()
            if now_dt > expires_dt:
                return "expired"
        except ValueError:
            pass
    return status


def load_project_operator_intents(
    local_files: dict[str, Any],
    *,
    include_all: bool = False,
    limit: int = 20,
) -> list[dict[str, Any]]:
    intents_dir = project_operator_intents_dir(local_files)
    if not intents_dir.exists() or not intents_dir.is_dir():
        return []
    rows: list[dict[str, Any]] = []
    for path in sorted(intents_dir.glob("*.json"), key=lambda item: item.stat().st_mtime_ns, reverse=True):
        payload = load_json(path, {})
        if not isinstance(payload, dict):
            continue
        intent = payload.get("intent", payload)
        if not isinstance(intent, dict):
            continue
        normalized = dict(intent)
        normalized["path"] = str(path)
        normalized["status"] = operator_intent_status(normalized)
        if include_all or normalized["status"] in OPERATOR_INTENT_PENDING_STATUSES:
            rows.append(normalized)
        if len(rows) >= max(int(limit), 1):
            break
    return rows


def operator_intent_id(intent_type: str) -> str:
    seed = f"{intent_type}:{time.time_ns()}:{os.getpid()}"
    digest = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:10]
    return f"{time.strftime('%Y%m%d_%H%M%S')}_{slugify(intent_type, 'intent')}_{digest}"


def build_project_operator_intent_payload(
    *,
    ops_root: Path,
    project_name: str,
    machine_id_arg: str,
    intent_type: str,
    objective: str,
    allowed_scope: list[str],
    verification: list[str],
    stop_condition: list[str],
    source_command: str,
    expiry_minutes: int,
    write: bool,
) -> dict[str, Any]:
    project = project_entry(ops_root, project_name)
    if project is None:
        raise RuntimeError(f"project not found: {project_name}")
    machine_id = normalize_machine_id(machine_id_arg, ops_root)
    if not machine_id:
        raise RuntimeError("Unable to resolve local machine id. Pass --machine-id explicitly.")
    project_id = str(project.get("project_id") or project_name)
    display_name = str(project.get("display_name") or project_id)
    local_files = ensure_local_project_files(
        machine_id=machine_id,
        project_id=project_id,
        display_name=display_name,
        create=True,
    )
    safe_type = slugify(intent_type, "operator_intent")
    safe_expiry_minutes = max(int(expiry_minutes), 1)
    created_epoch = time.time()
    intent_id = operator_intent_id(safe_type)
    intent = {
        "schema": "clutch.operator_intent.v1",
        "intent_id": intent_id,
        "intent_type": safe_type,
        "project_id": project_id,
        "display_name": display_name,
        "machine_id": machine_id,
        "created_at_local": local_timestamp_from_epoch(created_epoch),
        "expires_at_local": local_timestamp_from_epoch(created_epoch + safe_expiry_minutes * 60),
        "objective": str(objective or "").strip(),
        "allowed_scope": [str(item).strip() for item in allowed_scope if str(item or "").strip()],
        "verification_commands": [str(item).strip() for item in verification if str(item or "").strip()],
        "stop_conditions": [str(item).strip() for item in stop_condition if str(item or "").strip()],
        "approval_boundaries": [
            "This web intent does not authorize hardware-affecting actions.",
            "This web intent does not authorize sudo, system service, kernel, network, driver, or credential changes.",
            "The next Codex natural-language prompt still controls the actual task scope.",
        ],
        "source_web_command": str(source_command or "").strip(),
        "status": "pending",
    }
    path = project_operator_intents_dir(local_files) / f"{intent_id}.json"
    if write:
        save_json(path, {"schema": "clutch.operator_intent_file.v1", "intent": intent})
    pending = load_project_operator_intents(local_files, include_all=False, limit=10)
    if write:
        pending = [intent, *[item for item in pending if item.get("intent_id") != intent_id]][:10]
    return {
        "schema": "clutch.project_operator_intent.v1",
        "ok": True,
        "project_id": project_id,
        "display_name": display_name,
        "machine_id": machine_id,
        "intent": intent,
        "intent_path": str(path),
        "wrote": bool(write),
        "pending_intents": pending,
        "pending_intent_count": len(pending),
        "recommended_next_prompt": (
            "Tell Codex the concrete natural-language task now. "
            "For away work, say `자리비움 개발해` only after the desired objective is clear."
        ),
    }


def build_project_operator_intents_payload(
    *,
    ops_root: Path,
    project_name: str,
    machine_id_arg: str,
    include_all: bool,
    limit: int,
) -> dict[str, Any]:
    project = project_entry(ops_root, project_name)
    if project is None:
        raise RuntimeError(f"project not found: {project_name}")
    machine_id = normalize_machine_id(machine_id_arg, ops_root)
    if not machine_id:
        raise RuntimeError("Unable to resolve local machine id. Pass --machine-id explicitly.")
    project_id = str(project.get("project_id") or project_name)
    display_name = str(project.get("display_name") or project_id)
    local_files = ensure_local_project_files(
        machine_id=machine_id,
        project_id=project_id,
        display_name=display_name,
        create=False,
    )
    intents = load_project_operator_intents(local_files, include_all=include_all, limit=limit)
    return {
        "schema": "clutch.project_operator_intents.v1",
        "ok": True,
        "project_id": project_id,
        "display_name": display_name,
        "machine_id": machine_id,
        "operator_intents_dir": str(project_operator_intents_dir(local_files)),
        "include_all": bool(include_all),
        "pending_intent_count": sum(1 for item in intents if item.get("status") in OPERATOR_INTENT_PENDING_STATUSES),
        "intent_count": len(intents),
        "intents": intents,
    }


def existing_away_plan_status(plan_path: Path) -> dict[str, Any]:
    text = plan_path.read_text(encoding="utf-8") if plan_path.exists() else ""
    expires_at = ""
    expired = False
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if line.startswith("Expires:"):
            expires_at = line.split(":", 1)[1].strip()
            break
    if expires_at:
        try:
            expires_dt = datetime.fromisoformat(expires_at)
            now_dt = datetime.now(expires_dt.tzinfo) if expires_dt.tzinfo else datetime.now()
            expired = now_dt > expires_dt
        except ValueError:
            expired = False
    needs_objective = (
        "Ready for queued away work: yes" not in text
        or "TODO: ask the operator for the away-development objective" in text
    )
    return {
        "plan_text": text,
        "expires_at_local": expires_at,
        "expired": expired,
        "needs_operator_objective": needs_objective,
        "ready_for_queued_away_work": bool(text.strip()) and not expired and not needs_objective,
    }


def normalize_away_prompt(prompt: str) -> str:
    lowered = str(prompt or "").strip().lower()
    normalized_chars = []
    for char in lowered:
        if char.isalnum():
            normalized_chars.append(char)
        else:
            normalized_chars.append(" ")
    return " ".join("".join(normalized_chars).split())


def away_prompt_continuation_match(normalized_prompt: str) -> tuple[bool, str]:
    normalized = str(normalized_prompt or "").strip()
    if not normalized:
        return True, "empty_prompt"
    if normalized in AWAY_CONTINUATION_PROMPT_ALIASES:
        return True, "exact_alias"
    for alias in AWAY_CONTINUATION_PROMPT_ALIASES:
        prefix = f"{alias} "
        if normalized.startswith(prefix):
            suffix = normalized[len(prefix) :].strip()
            if suffix in {"complete", "completed", "done", "finished"}:
                return True, "alias_with_completion_suffix"
            if AWAY_CONTINUATION_VERSION_SUFFIX_RE.match(suffix):
                return True, "alias_with_release_status_suffix"
    return False, ""


def away_prompt_scope_assessment(*, prompt: str, objective: str) -> dict[str, Any]:
    normalized = normalize_away_prompt(prompt)
    continuation_prompt, continuation_reason = away_prompt_continuation_match(normalized)
    scope_review_required = bool(normalized and not continuation_prompt)
    recommendations = []
    if scope_review_required:
        recommendations.extend(
            [
                "Treat this as a fresh active operator instruction, not a queued away-development continuation.",
                "Compare the instruction with the recorded away objective and allowed scope before continuing.",
                "If the instruction is outside the recorded away plan, archive the current plan and create a fresh one.",
            ]
        )
    return {
        "prompt": prompt,
        "normalized_prompt": normalized,
        "continuation_prompt": continuation_prompt,
        "continuation_prompt_reason": continuation_reason,
        "scope_review_required": scope_review_required,
        "stop_reason": "new_operator_instruction_requires_scope_review" if scope_review_required else "",
        "recommended_next_action": "compare_operator_instruction_with_away_plan_scope_or_archive_refresh"
        if scope_review_required
        else "continue_within_away_plan_scope",
        "objective": objective,
        "recommendations": recommendations,
    }


def text_matches_any(text: str, needles: list[str]) -> bool:
    lowered = str(text or "").lower()
    return any(needle in lowered for needle in needles)


def text_has_explicit_publication_target(text: str) -> bool:
    lowered = f" {str(text or '').lower()} "
    return any(
        marker in lowered
        for marker in [
            " named ",
            " name:",
            " name=",
            " target:",
            " target=",
            " repo:",
            " repository:",
            " github.com/",
            " git" + "@github.com:",
            ".git",
        ]
    )


def away_publication_policy(
    *,
    preapproved_actions: list[str],
    online_backup: dict[str, Any],
    versioning_readiness: dict[str, Any],
) -> dict[str, Any]:
    preapproved_text = "\n".join(str(item or "") for item in preapproved_actions)
    wip_preapproved = text_matches_any(
        preapproved_text,
        [
            "wip branch",
            "wip-branch",
            "backup branch",
            "backup-branch",
            "dirty branch",
            "dirty wip",
            "unfinished work",
        ],
    )
    online_backup_preapproved = text_matches_any(
        preapproved_text,
        [
            "online backup",
            "backup publication",
            "backup publish",
            "project-online-backup",
        ],
    )
    clean_publication_preapproved = text_matches_any(
        preapproved_text,
        [
            "project-online-publish",
            "online publication",
            "canonical publication",
            "protected branch",
            "protected-branch",
            "main branch",
            "publish main",
        ],
    )
    metadata_publication_preapproved = text_matches_any(
        preapproved_text,
        [
            "metadata publication",
            "snapshot metadata",
            "project-snapshot-promote",
            "metadata branch",
        ],
    )
    new_remote_preapproved = text_matches_any(
        preapproved_text,
        [
            "new online remote",
            "remote creation",
            "create remote",
            "create github repo",
            "create repository",
            "repo creation",
        ],
    ) and text_has_explicit_publication_target(preapproved_text)

    online_backup_enabled = int(online_backup.get("enabled_count") or 0)
    online_backup_approval_required = int(online_backup.get("approval_required_count") or 0)
    online_backup_unconfigured = int(online_backup.get("unconfigured_count") or 0)
    routine_publish_ready = bool(versioning_readiness.get("routine_publish_ready"))
    reproducibility_ready = bool(versioning_readiness.get("reproducibility_ready"))
    needs_publish_repo_count = int(versioning_readiness.get("needs_publish_repo_count") or 0)
    dirty_repo_count = int(versioning_readiness.get("dirty_repo_count") or 0)

    def explicit_or_required(preapproved: bool, ready: bool, ready_status: str, blocked_status: str) -> str:
        if not preapproved:
            return "requires_explicit_away_preapproval"
        return ready_status if ready else blocked_status

    online_backup_ready = (
        online_backup_enabled > 0
        and online_backup_approval_required == 0
        and online_backup_unconfigured == 0
    )
    clean_publication_ready = routine_publish_ready and dirty_repo_count == 0
    metadata_publication_ready = (
        metadata_publication_preapproved
        and reproducibility_ready
        and routine_publish_ready
        and dirty_repo_count == 0
    )
    wip_branch_ready = online_backup_ready
    policy_items = [
        {
            "name": "local_checkpoints_and_backups",
            "status": "allowed_without_fresh_approval",
            "reason": "machine-local backups, git bundles, project snapshots, and local checkpoint refs do not publish online",
        },
        {
            "name": "wip_backup_branch_push",
            "status": explicit_or_required(
                wip_preapproved,
                wip_branch_ready,
                "preapproved_and_project_policy_ready",
                "preapproved_but_project_policy_not_ready",
            ),
            "preapproved": wip_preapproved,
            "project_policy_ready": wip_branch_ready,
            "enabled_repo_count": online_backup_enabled,
            "approval_required_count": online_backup_approval_required,
            "unconfigured_count": online_backup_unconfigured,
            "reason": "dirty or unfinished work may only leave the machine through an explicitly approved backup/WIP branch path",
        },
        {
            "name": "online_backup_publication",
            "status": explicit_or_required(
                online_backup_preapproved,
                online_backup_ready,
                "preapproved_and_project_policy_ready",
                "preapproved_but_project_policy_not_ready",
            ),
            "preapproved": online_backup_preapproved,
            "project_policy_ready": online_backup_ready,
            "enabled_repo_count": online_backup_enabled,
            "approval_required_count": online_backup_approval_required,
            "unconfigured_count": online_backup_unconfigured,
            "reason": "existing online backup remotes still need explicit away-plan preapproval before unattended publication",
        },
        {
            "name": "clean_online_publication",
            "status": explicit_or_required(
                clean_publication_preapproved,
                clean_publication_ready,
                "preapproved_and_versioning_ready",
                "preapproved_but_versioning_not_ready",
            ),
            "preapproved": clean_publication_preapproved,
            "versioning_ready": clean_publication_ready,
            "needs_publish_repo_count": needs_publish_repo_count,
            "dirty_repo_count": dirty_repo_count,
            "reason": "canonical/protected branch publication is limited to clean repos and the configured publisher policy",
        },
        {
            "name": "metadata_branch_publication",
            "status": explicit_or_required(
                metadata_publication_preapproved,
                metadata_publication_ready,
                "preapproved_and_snapshot_policy_ready",
                "preapproved_but_snapshot_policy_not_ready",
            ),
            "preapproved": metadata_publication_preapproved,
            "snapshot_policy_ready": metadata_publication_ready,
            "reproducibility_ready": reproducibility_ready,
            "reason": "snapshot metadata publication needs explicit preapproval plus clean versioning and reproducibility readiness",
        },
        {
            "name": "new_online_remote_or_repo_creation",
            "status": "explicitly_preapproved_high_risk" if new_remote_preapproved else "requires_fresh_active_approval",
            "preapproved": new_remote_preapproved,
            "reason": "new online remotes or repositories change project publication scope and must be named explicitly",
        },
    ]
    requires_fresh_approval = [
        item["name"]
        for item in policy_items
        if str(item.get("status") or "").startswith("requires_")
    ]
    preapproved_blocked = [
        item["name"]
        for item in policy_items
        if "but_" in str(item.get("status") or "")
    ]
    allowed_now = [
        item["name"]
        for item in policy_items
        if str(item.get("status") or "") in {
            "allowed_without_fresh_approval",
            "preapproved_by_away_plan",
            "preapproved_and_project_policy_ready",
            "preapproved_and_versioning_ready",
            "preapproved_and_snapshot_policy_ready",
            "explicitly_preapproved_high_risk",
        }
    ]
    return {
        "schema": "clutch.away_publication_policy.v1",
        "allowed_now": allowed_now,
        "requires_fresh_approval": requires_fresh_approval,
        "preapproved_but_blocked": preapproved_blocked,
        "summary": {
            "allowed_now_count": len(allowed_now),
            "requires_fresh_approval_count": len(requires_fresh_approval),
            "preapproved_but_blocked_count": len(preapproved_blocked),
            "explicit_preapproval_count": len(preapproved_actions),
        },
        "items": policy_items,
    }


def away_publication_skipped_items(publication_policy: dict[str, Any]) -> list[dict[str, Any]]:
    if not isinstance(publication_policy, dict):
        return []
    requires_fresh = set(publication_policy.get("requires_fresh_approval", []) or [])
    preapproved_blocked = set(publication_policy.get("preapproved_but_blocked", []) or [])
    skipped: list[dict[str, Any]] = []
    for item in publication_policy.get("items", []):
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or "")
        status = str(item.get("status") or "")
        if name in requires_fresh or status.startswith("requires_"):
            skipped.append(
                {
                    "kind": "away_publication_policy",
                    "severity": "needs_approval",
                    "name": name,
                    "status": status,
                    "message": "publication path requires explicit away-plan preapproval before unattended use",
                }
            )
        elif name in preapproved_blocked or "but_" in status:
            skipped.append(
                {
                    "kind": "away_publication_policy",
                    "severity": "blocked",
                    "name": name,
                    "status": status,
                    "message": "publication path was preapproved but current project readiness blocks it",
                }
            )
    return skipped


def away_plan_safety_guidance(
    *,
    project_id: str,
    stop_reason: str,
    plan_present: bool,
) -> dict[str, Any]:
    ctl = str(FOUNDATION_ROOT / "scripts" / "clutch_ctl.py")
    recommendations = [
        "If the active operator gives new work outside the away plan objective/scope, stop treating queued away authority as active and create a fresh plan.",
    ]
    commands: dict[str, str] = {}
    if plan_present and stop_reason in {"away_plan_expired", "missing_operator_objective"}:
        recommendations.append("Archive the stale or incomplete away plan before accepting more queued away prompts.")
        commands["archive_plan"] = command_line(
            [
                "python3",
                ctl,
                "project-away-plan",
                "--project",
                project_id,
                "--clear",
                "--skip-runtime",
            ]
        )
    if stop_reason in {"missing_away_plan", "away_plan_expired", "missing_operator_objective"}:
        recommendations.append("Create a new away plan with an explicit objective, scope, preapprovals, stop conditions, and validity window before queued away work continues.")
        commands["create_new_plan"] = command_line(
            [
                "python3",
                ctl,
                "project-away-plan",
                "--project",
                project_id,
                "--objective",
                "<objective>",
                "--allowed-scope",
                "<scope>",
                "--verification",
                "<verification-command>",
                "--valid-hours",
                "<hours>",
                "--write",
            ]
        )
    return {
        "stop_reason": stop_reason,
        "recommendations": recommendations,
        "recommended_commands": commands,
    }


def away_plan_summary(local_files: dict[str, Any]) -> dict[str, Any]:
    project_root = str(local_files.get("project_root") or "").strip()
    plan_path = Path(project_root).expanduser() / AWAY_PLAN_FILENAME if project_root else Path("")
    if not project_root or not plan_path.exists():
        project_id = str(local_files.get("project_id") or "")
        return {
            "present": False,
            "path": str(plan_path) if project_root else "",
            "ready_for_queued_away_work": False,
            "expired": False,
            "needs_operator_objective": True,
            "expires_at_local": "",
            "safety_guidance": away_plan_safety_guidance(
                project_id=project_id,
                stop_reason="missing_away_plan",
                plan_present=False,
            ),
        }
    status = existing_away_plan_status(plan_path)
    stop_reason = ""
    if bool(status.get("expired")):
        stop_reason = "away_plan_expired"
    elif bool(status.get("needs_operator_objective")):
        stop_reason = "missing_operator_objective"
    return {
        "present": True,
        "path": str(plan_path),
        "ready_for_queued_away_work": bool(status.get("ready_for_queued_away_work")),
        "expired": bool(status.get("expired")),
        "needs_operator_objective": bool(status.get("needs_operator_objective")),
        "expires_at_local": str(status.get("expires_at_local") or ""),
        "stop_reason": stop_reason,
        "safety_guidance": away_plan_safety_guidance(
            project_id=str(local_files.get("project_id") or ""),
            stop_reason=stop_reason,
            plan_present=True,
        )
        if stop_reason
        else {},
    }


def markdown_sections(text: str) -> dict[str, str]:
    sections: dict[str, list[str]] = {}
    current = ""
    for raw_line in text.splitlines():
        line = raw_line.rstrip()
        if line.startswith("## "):
            current = line[3:].strip()
            sections.setdefault(current, [])
            continue
        if current:
            sections.setdefault(current, []).append(line)
    return {key: "\n".join(value).strip() for key, value in sections.items()}


def markdown_section_bullets(section_text: str) -> list[str]:
    result: list[str] = []
    for raw_line in section_text.splitlines():
        line = raw_line.strip()
        if line.startswith("- "):
            result.append(line[2:].strip())
    return result


def markdown_section_body(section_text: str) -> str:
    lines = []
    for raw_line in section_text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if line.startswith("- "):
            continue
        lines.append(line)
    return "\n".join(lines).strip()


def resolve_project_from_context(
    *,
    ops_root: Path,
    project_name: str,
    machine_id: str | None,
    cwd: Path,
) -> tuple[dict[str, Any], str]:
    if project_name:
        project = project_entry(ops_root, project_name)
        if project is None:
            raise RuntimeError(f"project not found: {project_name}")
        return project, "explicit_project"

    matched = find_project_for_path(project_entries(ops_root), cwd)
    if matched is not None:
        return matched, "cwd_match"

    thread_id = current_thread_id("")
    if thread_id:
        for binding in active_bindings_for_machine(machine_id):
            if binding.get("thread_id") != thread_id:
                continue
            project_id = str(binding.get("project_id") or "")
            project = project_entry(ops_root, project_id)
            if project is not None:
                return project, "current_thread_binding"

    machine_bindings = active_bindings_for_machine(machine_id)
    project_ids = dedupe_strings([str(item.get("project_id") or "") for item in machine_bindings])
    if len(project_ids) == 1:
        project = project_entry(ops_root, project_ids[0])
        if project is not None:
            return project, "single_machine_binding"

    raise RuntimeError("Unable to resolve project from --project, cwd, or current CLUTCH binding.")


def away_plan_markdown(
    *,
    project_status: dict[str, Any],
    objective: str,
    allowed_actions: list[str],
    preapproved_actions: list[str],
    forbidden_actions: list[str],
    verification_commands: list[str],
    stop_conditions: list[str],
    msi_policy: str,
    checkpoint_policy: str,
    time_budget_minutes: int,
    valid_hours: int,
    expires_at_local: str,
) -> str:
    project_id = str(project_status.get("project_id") or "")
    display_name = str(project_status.get("display_name") or project_id)
    machine_id = str(project_status.get("machine_id") or "")
    workspace_path = str(project_status.get("workspace_path") or "")
    self_hosting_clutch = project_id == "clutch"
    sync_summary = project_status.get("sync_summary", {}) if isinstance(project_status.get("sync_summary"), dict) else {}
    backups = project_status.get("backups", {}) if isinstance(project_status.get("backups"), dict) else {}
    online_backup = project_status.get("online_backup", {}) if isinstance(project_status.get("online_backup"), dict) else {}
    versioning = (
        project_status.get("versioning_readiness", {})
        if isinstance(project_status.get("versioning_readiness"), dict)
        else {}
    )
    bindings = project_status.get("bindings", {}) if isinstance(project_status.get("bindings"), dict) else {}
    backup_plan = project_status.get("backup_plan", {}) if isinstance(project_status.get("backup_plan"), dict) else {}
    sync_payload = project_status.get("sync", {}) if isinstance(project_status.get("sync"), dict) else {}
    attention_items = project_status.get("attention_items", [])
    if not isinstance(attention_items, list):
        attention_items = []

    repo_lines = []
    for item in sync_payload.get("repo_results", []):
        if not isinstance(item, dict):
            continue
        repo_lines.append(
            f"`{item.get('repo_id')}` status={item.get('status')} path={item.get('path')}"
        )

    backup_lines = []
    for item in backup_plan.get("repo_results", []):
        if not isinstance(item, dict):
            continue
        dirty = "dirty" if item.get("dirty") else "clean"
        backup_lines.append(
            f"`{item.get('repo_id')}` backup={item.get('status')} head={item.get('head')} {dirty}"
        )

    attention_lines = []
    for item in attention_items:
        if not isinstance(item, dict):
            continue
        prefix = f"{item.get('severity', 'info')}:{item.get('kind', 'attention')}"
        detail = str(item.get("message") or "")
        repo_id = str(item.get("repo_id") or "")
        status = str(item.get("status") or "")
        suffix = " ".join(part for part in [f"repo={repo_id}" if repo_id else "", f"status={status}" if status else ""] if part)
        attention_lines.append(f"{prefix} {suffix} {detail}".strip())

    objective_text = objective.strip() or "TODO: ask the operator for the away-development objective before starting autonomous work."
    time_budget_text = f"{time_budget_minutes} minutes" if time_budget_minutes > 0 else "not specified"
    ready_text = "yes" if objective.strip() else "no"

    return "\n".join(
        [
            f"# {display_name} Away Development Plan",
            "",
            "Schema: `clutch.project_away_plan.v1`",
            f"Generated: {current_local_timestamp()}",
            f"Valid hours: {valid_hours}",
            f"Expires: {expires_at_local}",
            f"Ready for queued away work: {ready_text}",
            "",
            "## Project",
            "",
            f"- Project: `{project_id}`",
            f"- Machine: `{machine_id}`",
            f"- Workspace: `{workspace_path}`",
            f"- Self-hosting CLUTCH development: `{self_hosting_clutch}`",
            f"- Time budget: {time_budget_text}",
            f"- WORKER policy: `{msi_policy}`",
            "",
            "## Operator Objective",
            "",
            objective_text,
            "",
            "## Away Work Principles",
            "",
            "- Default authority is limited to actions that do not need fresh active user approval.",
            "- A normally approval-gated action is allowed during away work only when it is explicitly listed in this plan's preapproval section.",
            "- Continue toward the stated objective until it is complete or a stop condition is hit.",
            "- If the stated objective is complete and queued away prompts continue, switch to debugging, stabilization, test coverage, and low-risk optimization inside the same approval boundary.",
            "- Preserve progress with before-work, intermediate, major-checkpoint, and final checkpoint backups.",
            "",
            "## Current Project Snapshot",
            "",
            f"- status_ok: `{bool(project_status.get('ok'))}`",
            f"- required_repo_count: `{sync_summary.get('required_repo_count', 0)}`",
            f"- required_sync_ready_count: `{sync_summary.get('required_sync_ready_count', 0)}`",
            f"- required_sync_blocked_count: `{sync_summary.get('required_blocked_count', 0)}`",
            f"- backup_snapshot_count: `{backups.get('snapshot_count', 0)}`",
            f"- online_backup_enabled_count: `{online_backup.get('enabled_count', 0)}`",
            f"- online_backup_approval_required_count: `{online_backup.get('approval_required_count', 0)}`",
            f"- online_backup_unconfigured_count: `{online_backup.get('unconfigured_count', 0)}`",
            f"- versioning_ok: `{bool(versioning.get('ok'))}`",
            f"- versioning_blocking_finding_count: `{versioning.get('blocking_finding_count', 0)}`",
            f"- versioning_needs_publish_repo_count: `{versioning.get('needs_publish_repo_count', 0)}`",
            f"- project_main_count: `{bindings.get('project_main_count', 0)}`",
            f"- project_worker_count: `{bindings.get('project_worker_count', 0)}`",
            f"- project_observer_count: `{bindings.get('project_observer_count', 0)}`",
            "",
            "## Repo Sync State",
            "",
            markdown_bullets(repo_lines),
            "",
            "## Backup / Dirty State",
            "",
            markdown_bullets(backup_lines),
            "",
            "## Attention Items",
            "",
            markdown_bullets(attention_lines),
            "",
            "## Allowed Without Further Approval",
            "",
            markdown_bullets(allowed_actions),
            "",
            "## Explicitly Preapproved During Away Work",
            "",
            markdown_bullets(preapproved_actions),
            "",
            "## Checkpoint Policy",
            "",
            checkpoint_policy,
            "",
            "## Away Publication Policy",
            "",
            "- Machine-local backups, git bundles, project snapshots, and local checkpoint refs are allowed inside the away scope.",
            "- WIP or backup branch pushes require explicit away-plan preapproval or an existing saved project policy.",
            "- Existing approved online backup publication requires explicit away-plan preapproval before unattended use.",
            "- Canonical/protected branch publication requires explicit away-plan preapproval, clean repos, and the configured publisher policy.",
            "- New online remotes or repository creation require exact explicit preapproval naming the target.",
            "",
            "## Requires Fresh Active User Approval",
            "",
            markdown_bullets(forbidden_actions),
            "",
            "## Stop Conditions",
            "",
            markdown_bullets(stop_conditions),
            "",
            "## Verification Commands",
            "",
            markdown_bullets(verification_commands),
            "",
            "## Completion Report",
            "",
            "- summarize files changed, commands run, tests passed/failed, and remaining risks",
            "- report any skipped action that would require active user approval",
            "- leave dirty work protected by local backup, WIP commit, or approved backup branch",
            "",
            "## Queued Prompt Rule",
            "",
            "When a later prompt says `continue away development` or `자리비움 개발 진행해`, read this file first. If the plan is expired, missing an objective, or asks for an unsafe action, stop and ask the operator.",
        ]
    ) + "\n"


def build_project_away_plan_payload(
    *,
    ops_root: Path,
    project_name: str,
    machine_id_arg: str,
    objective: str,
    allowed_scope: list[str],
    preapproved_action: list[str],
    forbidden_action: list[str],
    verification: list[str],
    stop_condition: list[str],
    msi_policy: str,
    checkpoint_policy: str,
    time_budget_minutes: int,
    valid_hours: int,
    write: bool,
    clear: bool,
    backups_root: Path,
    skip_runtime: bool,
) -> dict[str, Any]:
    project = project_entry(ops_root, project_name)
    if project is None:
        raise RuntimeError(f"project not found: {project_name}")
    machine_id = normalize_machine_id(machine_id_arg, ops_root)
    if not machine_id:
        raise RuntimeError("Unable to resolve local machine id. Pass --machine-id explicitly.")
    display_name = str(project.get("display_name") or project.get("project_id") or "Project")
    local_files = ensure_local_project_files(
        machine_id=machine_id,
        project_id=str(project.get("project_id") or ""),
        display_name=display_name,
        create=True,
    )
    plan_path = project_away_plan_path(local_files)
    existing_plan_present = plan_path.exists()
    archived_path = ""
    inspect_existing = bool(
        existing_plan_present
        and not clear
        and not write
        and not objective.strip()
        and not allowed_scope
        and not preapproved_action
        and not forbidden_action
        and not verification
        and not stop_condition
        and not checkpoint_policy.strip()
    )
    if inspect_existing:
        existing_status = existing_away_plan_status(plan_path)
        stop_reason = ""
        if bool(existing_status.get("expired")):
            stop_reason = "away_plan_expired"
        elif bool(existing_status.get("needs_operator_objective")):
            stop_reason = "missing_operator_objective"
        safety_guidance = (
            away_plan_safety_guidance(
                project_id=str(project.get("project_id") or ""),
                stop_reason=stop_reason,
                plan_present=True,
            )
            if stop_reason
            else {}
        )
        return {
            "schema": "clutch.project_away_plan.v1",
            "project_id": project.get("project_id"),
            "display_name": display_name,
            "machine_id": machine_id,
            "away_plan_path": str(plan_path),
            "existing_plan_present": True,
            "wrote": False,
            "cleared": False,
            "expired": existing_status["expired"],
            "expires_at_local": existing_status["expires_at_local"],
            "ready_for_queued_away_work": existing_status["ready_for_queued_away_work"],
            "needs_operator_objective": existing_status["needs_operator_objective"],
            "stop_reason": stop_reason,
            "safety_guidance": safety_guidance,
            "questions": [] if existing_status["ready_for_queued_away_work"] else [
                "What should Codex accomplish while the operator is away?",
                "Should the stale or incomplete away plan be archived before creating a new one?",
            ],
            "plan_text": existing_status["plan_text"],
        }
    if clear:
        if existing_plan_present:
            archive_name = f"AWAY_DEVELOPMENT_PLAN.cleared_{time.strftime('%Y%m%d_%H%M%S')}.md"
            archive_path = plan_path.with_name(archive_name)
            plan_path.replace(archive_path)
            archived_path = str(archive_path)
        return {
            "schema": "clutch.project_away_plan.v1",
            "project_id": project.get("project_id"),
            "display_name": display_name,
            "machine_id": machine_id,
            "away_plan_path": str(plan_path),
            "existing_plan_present": existing_plan_present,
            "cleared": existing_plan_present,
            "archived_path": archived_path,
            "wrote": False,
            "ready_for_queued_away_work": False,
            "needs_operator_objective": True,
            "recommended_next_action": "create_new_away_plan_before_queued_away_work",
            "safety_guidance": away_plan_safety_guidance(
                project_id=str(project.get("project_id") or ""),
                stop_reason="missing_away_plan",
                plan_present=False,
            ),
        }

    safe_valid_hours = max(int(valid_hours), 1)
    expires_at_local = local_timestamp_from_epoch(time.time() + safe_valid_hours * 60 * 60)
    allowed_actions = default_away_allowed_actions(msi_policy) + [str(item) for item in allowed_scope]
    preapproved_actions = [str(item) for item in preapproved_action if str(item or "").strip()]
    forbidden_actions = default_away_forbidden_actions() + [str(item) for item in forbidden_action]
    checkpoint_text = str(checkpoint_policy or "").strip() or (
        "Use machine-local project backups and project-snapshot manifests before work, "
        "at intermediate milestones, at major behavior changes, and at final report. "
        "Use backup/WIP branches only when the away plan or saved project policy explicitly approves them."
    )
    verification_commands = verification or [
        "python3 scripts/clutch_ctl.py project-status --project <project_id>",
        "python3 -m py_compile scripts/clutch_ctl.py",
    ]
    verification_commands = [item.replace("<project_id>", str(project.get("project_id") or "")) for item in verification_commands]
    stop_conditions = stop_condition or [
        "operator objective is missing or ambiguous",
        "work requires a forbidden action or fresh approval",
        "tests fail in a way that risks unrelated behavior",
        "repo state is dirty outside the allowed write scope",
        "WORKER or worker state conflicts with this plan",
    ]

    project_status = build_project_status_payload(
        ops_root=ops_root,
        project_name=str(project.get("project_id") or project_name),
        machine_id_arg=machine_id,
        backups_root=backups_root,
        backup_limit=3,
        include_runtime=not skip_runtime,
        collab_stale_sec=DEFAULT_COLLAB_STALE_SEC,
    )
    plan_text = away_plan_markdown(
        project_status=project_status,
        objective=objective,
        allowed_actions=allowed_actions,
        preapproved_actions=preapproved_actions,
        forbidden_actions=forbidden_actions,
        verification_commands=verification_commands,
        stop_conditions=stop_conditions,
        msi_policy=msi_policy,
        checkpoint_policy=checkpoint_text,
        time_budget_minutes=max(int(time_budget_minutes), 0),
        valid_hours=safe_valid_hours,
        expires_at_local=expires_at_local,
    )
    if write:
        plan_path.write_text(plan_text, encoding="utf-8")

    ready = bool(objective.strip())
    questions = []
    if not ready:
        questions.append("What should Codex accomplish while the operator is away?")
    questions.extend(
        [
            "Which paths or modules are allowed to change?",
            "Which verification commands should be run before reporting done?",
            "Should WORKER be used through the active project runbook, for code work only, manually only, or not at all?",
        ]
    )
    return {
        "schema": "clutch.project_away_plan.v1",
        "project_id": project.get("project_id"),
        "display_name": display_name,
        "machine_id": machine_id,
        "away_plan_path": str(plan_path),
        "existing_plan_present": existing_plan_present,
        "wrote": bool(write),
        "cleared": False,
        "ready_for_queued_away_work": ready,
        "needs_operator_objective": not ready,
        "expires_at_local": expires_at_local,
        "msi_policy": msi_policy,
        "questions": questions,
        "write_command_hint": command_line(
            [
                "python3",
                str(FOUNDATION_ROOT / "scripts" / "clutch_ctl.py"),
                "project-away-plan",
                "--project",
                str(project.get("project_id") or project_name),
                "--objective",
                "<objective>",
                "--write",
            ]
        ),
        "project_status_summary": {
            "ok": bool(project_status.get("ok")),
            "workspace_path": str(project_status.get("workspace_path") or ""),
            "attention_count": int(project_status.get("attention_count") or 0),
            "attention_severity_counts": project_status.get("attention_severity_counts", {}),
            "sync_summary": project_status.get("sync_summary", {}),
            "online_backup": project_status.get("online_backup", {}),
            "versioning_readiness": project_status.get("versioning_readiness", {}),
            "bindings": project_status.get("bindings", {}),
        },
        "plan_text": plan_text,
    }


def build_project_away_work_payload(
    *,
    ops_root: Path,
    project_name: str,
    machine_id_arg: str,
    cwd_arg: str,
    backups_root: Path,
    skip_runtime: bool,
    include_plan_text: bool,
) -> dict[str, Any]:
    machine_id = normalize_machine_id(machine_id_arg, ops_root)
    if not machine_id:
        raise RuntimeError("Unable to resolve local machine id. Pass --machine-id explicitly.")
    cwd = Path(cwd_arg or os.getcwd()).expanduser()
    project, resolution_source = resolve_project_from_context(
        ops_root=ops_root,
        project_name=project_name,
        machine_id=machine_id,
        cwd=cwd,
    )
    project_id = str(project.get("project_id") or "")
    display_name = str(project.get("display_name") or project_id)
    local_files = ensure_local_project_files(
        machine_id=machine_id,
        project_id=project_id,
        display_name=display_name,
        create=False,
    )
    pending_operator_intents = load_project_operator_intents(local_files, include_all=False, limit=10)
    plan_path = project_away_plan_path(local_files)
    if not plan_path.exists():
        safety_guidance = away_plan_safety_guidance(
            project_id=project_id,
            stop_reason="missing_away_plan",
            plan_present=False,
        )
        return {
            "schema": "clutch.project_away_work.v1",
            "project_id": project_id,
            "display_name": display_name,
            "machine_id": machine_id,
            "resolution_source": resolution_source,
            "away_plan_path": str(plan_path),
            "plan_present": False,
            "can_start": False,
            "stop_reason": "missing_away_plan",
            "recommended_next_action": "create_new_away_plan_before_queued_away_work",
            "safety_guidance": safety_guidance,
            "recommended_commands": safety_guidance["recommended_commands"],
            "operator_intents": pending_operator_intents,
            "pending_operator_intent_count": len(pending_operator_intents),
            "questions": [
                "Create an away plan first with `project-away-plan --project <project_id> --objective ... --write`."
            ],
        }

    status = existing_away_plan_status(plan_path)
    text = str(status.get("plan_text") or "")
    sections = markdown_sections(text)
    objective = markdown_section_body(sections.get("Operator Objective", ""))
    principles = markdown_section_bullets(sections.get("Away Work Principles", ""))
    allowed_actions = markdown_section_bullets(sections.get("Allowed Without Further Approval", ""))
    preapproved_actions = markdown_section_bullets(sections.get("Explicitly Preapproved During Away Work", ""))
    checkpoint_policy = markdown_section_body(sections.get("Checkpoint Policy", ""))
    publication_policy_text = sections.get("Away Publication Policy", "").strip()
    forbidden_actions = markdown_section_bullets(sections.get("Requires Fresh Active User Approval", ""))
    stop_conditions = markdown_section_bullets(sections.get("Stop Conditions", ""))
    verification_commands = markdown_section_bullets(sections.get("Verification Commands", ""))
    completion_report = markdown_section_bullets(sections.get("Completion Report", ""))
    queued_rule = markdown_section_body(sections.get("Queued Prompt Rule", ""))
    stop_reason = ""
    if bool(status.get("expired")):
        stop_reason = "away_plan_expired"
    elif bool(status.get("needs_operator_objective")) or not objective:
        stop_reason = "missing_operator_objective"
    safety_guidance = away_plan_safety_guidance(
        project_id=project_id,
        stop_reason=stop_reason,
        plan_present=True,
    )
    project_status = build_project_status_payload(
        ops_root=ops_root,
        project_name=project_id,
        machine_id_arg=machine_id,
        backups_root=backups_root,
        backup_limit=3,
        include_runtime=not skip_runtime,
        collab_stale_sec=DEFAULT_COLLAB_STALE_SEC,
    )
    online_backup = (
        project_status.get("online_backup", {})
        if isinstance(project_status.get("online_backup"), dict)
        else {}
    )
    versioning_readiness = (
        project_status.get("versioning_readiness", {})
        if isinstance(project_status.get("versioning_readiness"), dict)
        else {}
    )
    publication_policy = away_publication_policy(
        preapproved_actions=preapproved_actions,
        online_backup=online_backup,
        versioning_readiness=versioning_readiness,
    )
    first_actions = [
        "Read the operator objective and stop conditions before editing.",
        "Inspect current git status and keep work inside the allowed scope.",
        "Create a local project backup before risky or broad edits.",
        "Run the recorded verification commands before reporting done.",
        "Report skipped items that require fresh active user approval.",
    ]
    if project_id == "clutch":
        first_actions.insert(
            0,
            "Treat this as self-hosted CLUTCH development; do not overwrite dirty foundation/ops state.",
        )
    ctl = str(FOUNDATION_ROOT / "scripts" / "clutch_ctl.py")
    recommended_commands = {
        "before_checkpoint": command_line(
            [
                "python3",
                ctl,
                "project-away-checkpoint",
                "--project",
                project_id,
                "--phase",
                "before",
                "--label",
                "<label>",
                "--skip-runtime",
                "--branch-policy",
                "local",
                "--verify-restore",
                "--restore-smoke",
                "--restore-wip",
                "--replace-restore-workspace",
                "--yes",
            ]
        ),
        "intermediate_checkpoint": command_line(
            [
                "python3",
                ctl,
                "project-away-checkpoint",
                "--project",
                project_id,
                "--phase",
                "intermediate",
                "--label",
                "<label>",
                "--skip-runtime",
                "--branch-policy",
                "local",
                "--verify-restore",
                "--restore-smoke",
                "--restore-wip",
                "--replace-restore-workspace",
                "--yes",
            ]
        ),
        "final_finish_local": command_line(
            [
                "python3",
                ctl,
                "project-away-finish",
                "--project",
                project_id,
                "--label",
                "<label>",
                "--skip-runtime",
                "--branch-policy",
                "local",
                "--restore-smoke",
                "--restore-wip",
                "--replace-restore-workspace",
                "--yes",
            ]
        ),
    }
    publication_allowed_now = set(
        str(item)
        for item in publication_policy.get("allowed_now", [])
        if str(item or "").strip()
    )
    if project_id == "clutch" and "metadata_branch_publication" in publication_allowed_now:
        recommended_commands["final_finish_with_approved_metadata_publish"] = command_line(
            [
                "python3",
                ctl,
                "project-away-finish",
                "--project",
                project_id,
                "--label",
                "<label>",
                "--skip-runtime",
                "--branch-policy",
                "local",
                "--promote-metadata",
                "--metadata-repo-id",
                "clutch-foundation",
                "--metadata-publish-policy",
                "approved-online",
                "--restore-smoke",
                "--restore-wip",
                "--replace-restore-workspace",
                "--yes",
            ]
        )
    payload = {
        "schema": "clutch.project_away_work.v1",
        "project_id": project_id,
        "display_name": display_name,
        "machine_id": machine_id,
        "resolution_source": resolution_source,
        "cwd": str(cwd),
        "away_plan_path": str(plan_path),
        "plan_present": True,
        "can_start": not bool(stop_reason),
        "stop_reason": stop_reason,
        "recommended_next_action": "continue_within_away_plan_scope" if not stop_reason else "archive_or_refresh_away_plan",
        "safety_guidance": safety_guidance,
        "expires_at_local": str(status.get("expires_at_local") or ""),
        "expired": bool(status.get("expired")),
        "needs_operator_objective": bool(status.get("needs_operator_objective")),
        "objective": objective,
        "away_work_principles": principles,
        "allowed_without_further_approval": allowed_actions,
        "explicitly_preapproved_during_away_work": preapproved_actions,
        "checkpoint_policy": checkpoint_policy,
        "publication_policy_text": publication_policy_text,
        "publication_policy": publication_policy,
        "requires_fresh_active_user_approval": forbidden_actions,
        "stop_conditions": stop_conditions,
        "verification_commands": verification_commands,
        "completion_report_rules": completion_report,
        "queued_prompt_rule": queued_rule,
        "first_actions": first_actions,
        "recommended_commands": recommended_commands,
        "operator_intents": pending_operator_intents,
        "pending_operator_intent_count": len(pending_operator_intents),
        "project_status_summary": {
            "ok": bool(project_status.get("ok")),
            "workspace_path": str(project_status.get("workspace_path") or ""),
            "attention_count": int(project_status.get("attention_count") or 0),
            "attention_items": project_status.get("attention_items", []),
            "attention_severity_counts": project_status.get("attention_severity_counts", {}),
            "sync_summary": project_status.get("sync_summary", {}),
            "snapshots": project_status.get("snapshots", {}),
            "online_backup": online_backup,
            "versioning_readiness": versioning_readiness,
            "bindings": project_status.get("bindings", {}),
        },
    }
    if stop_reason:
        payload["recommended_commands"].update(safety_guidance.get("recommended_commands", {}))
    if include_plan_text:
        payload["plan_text"] = text
    return payload


def compact_restore_readiness(payload: dict[str, Any]) -> dict[str, Any]:
    metadata = (
        payload.get("metadata_restore_plan", {})
        if isinstance(payload.get("metadata_restore_plan"), dict)
        else {}
    )
    local_snapshot = (
        payload.get("machine_local_snapshot_restore_plan", {})
        if isinstance(payload.get("machine_local_snapshot_restore_plan"), dict)
        else {}
    )
    backup = payload.get("backup_verify", {}) if isinstance(payload.get("backup_verify"), dict) else {}
    backup_match = (
        payload.get("backup_restore_plan_match", {})
        if isinstance(payload.get("backup_restore_plan_match"), dict)
        else {}
    )
    smoke = payload.get("restore_smoke", {}) if isinstance(payload.get("restore_smoke"), dict) else {}
    blockers = payload.get("blockers", []) if isinstance(payload.get("blockers"), list) else []
    warnings = payload.get("warnings", []) if isinstance(payload.get("warnings"), list) else []
    next_actions = payload.get("next_actions", []) if isinstance(payload.get("next_actions"), list) else []
    return {
        "ok": bool(payload.get("ok")),
        "ready_for_non_destructive_restore_review": bool(payload.get("ready_for_non_destructive_restore_review")),
        "ready_for_in_place_restore": bool(payload.get("ready_for_in_place_restore")),
        "requested_snapshot_id": str(payload.get("requested_snapshot_id") or ""),
        "requested_backup_snapshot_id": str(payload.get("requested_backup_snapshot_id") or ""),
        "metadata_available": bool(metadata.get("available")),
        "metadata_snapshot_id": str(metadata.get("snapshot_id") or ""),
        "machine_local_snapshot_available": bool(local_snapshot.get("available")),
        "machine_local_snapshot_id": str(local_snapshot.get("snapshot_id") or ""),
        "backup_available": bool(backup.get("available")),
        "backup_ok": bool(backup.get("ok")),
        "backup_snapshot_id": str(backup.get("snapshot_id") or ""),
        "backup_restore_plan_match": {
            "ok": bool(backup_match.get("ok")),
            "mode": str(backup_match.get("mode") or ""),
            "matched_plan_source": str(backup_match.get("matched_plan_source") or ""),
            "matched_plan_snapshot_id": str(backup_match.get("matched_plan_snapshot_id") or ""),
            "plan_repo_count": int(backup_match.get("plan_repo_count") or 0),
            "backup_repo_count": int(backup_match.get("backup_repo_count") or 0),
            "repo_head_match_count": int(backup_match.get("repo_head_match_count") or 0),
            "repo_head_mismatch_count": int(backup_match.get("repo_head_mismatch_count") or 0),
            "missing_backup_repo_count": int(backup_match.get("missing_backup_repo_count") or 0),
            "dirty_mismatch_count": int(backup_match.get("dirty_mismatch_count") or 0),
        },
        "restore_smoke": {
            "requested": bool(smoke.get("requested")),
            "executed": bool(smoke.get("executed")),
            "status": str(smoke.get("status") or ""),
            "failed_count": int(smoke.get("failed_count") or 0),
            "confirmation_required": bool(smoke.get("confirmation_required")),
            "restore_workspace": str(smoke.get("restore_workspace") or ""),
        },
        "blocker_count": len(blockers),
        "warning_count": len(warnings),
        "blockers": blockers,
        "warnings": warnings,
        "next_actions": next_actions,
    }


AWAY_CHECKPOINT_REF_OK_STATUSES = {
    "clean_ref_written",
    "tracked_state_matches_head",
    "wip_ref_written",
}
AWAY_CHECKPOINT_REF_WARNING_STATUSES = {
    "path_unmapped",
}


def away_checkpoint_gate(checkpoint: dict[str, Any]) -> dict[str, Any]:
    backup_snapshot_id = str(checkpoint.get("backup_snapshot_id") or "")
    project_snapshot_id = str(checkpoint.get("project_snapshot_id") or "")
    branch_policy = str(checkpoint.get("branch_policy") or "none")
    branch_items = checkpoint.get("branch_checkpoints", [])
    if not isinstance(branch_items, list):
        branch_items = []
    restore_verification = (
        checkpoint.get("restore_verification", {})
        if isinstance(checkpoint.get("restore_verification"), dict)
        else {}
    )
    restore_readiness = (
        restore_verification.get("readiness", {})
        if isinstance(restore_verification.get("readiness"), dict)
        else {}
    )
    blockers = []
    warnings = []
    next_actions = []

    artifacts_ok = bool(backup_snapshot_id and project_snapshot_id)
    if not artifacts_ok:
        blockers.append("checkpoint backup and project snapshot ids must both be present")
        next_actions.append("rerun project-away-checkpoint and inspect backup/snapshot errors")

    branch_ok_count = 0
    branch_warning_count = 0
    branch_blocking_count = 0
    branch_blockers = []
    branch_warnings = []
    if branch_policy == "local":
        for item in branch_items:
            if not isinstance(item, dict):
                continue
            repo_id = str(item.get("repo_id") or "")
            status = str(item.get("status") or "")
            details = str(item.get("details") or "")
            message = f"{repo_id}: {status}".strip(": ")
            if details:
                message = f"{message} ({details})"
            if status in AWAY_CHECKPOINT_REF_OK_STATUSES:
                branch_ok_count += 1
            elif status in AWAY_CHECKPOINT_REF_WARNING_STATUSES:
                branch_warning_count += 1
                branch_warnings.append(message)
            else:
                branch_blocking_count += 1
                branch_blockers.append(message)
        if branch_blockers:
            blockers.extend(f"local checkpoint ref failed: {item}" for item in branch_blockers)
            next_actions.append("inspect branch_checkpoints and rerun after fixing repo path/ref errors")
        if branch_warnings:
            warnings.extend(f"local checkpoint ref warning: {item}" for item in branch_warnings)
    else:
        branch_ok_count = 0

    restore_requested = bool(restore_verification.get("requested"))
    restore_ok = not restore_requested or bool(restore_readiness.get("ok"))
    if not restore_ok:
        blockers.append("restore verification did not pass")
        next_actions.append("inspect restore_verification.readiness before treating the checkpoint as safe")

    if not blockers:
        next_actions.append("checkpoint is safe to use as an away-development recovery point")

    return {
        "ok": bool(artifacts_ok and branch_blocking_count == 0 and restore_ok),
        "artifacts_ok": artifacts_ok,
        "backup_snapshot_id": backup_snapshot_id,
        "project_snapshot_id": project_snapshot_id,
        "artifact_pointer_count": int(checkpoint.get("artifact_pointer_count") or 0),
        "branch_policy": branch_policy,
        "branch_ref_count": len([item for item in branch_items if isinstance(item, dict)]),
        "branch_ref_ok_count": branch_ok_count,
        "branch_ref_warning_count": branch_warning_count,
        "branch_ref_blocking_count": branch_blocking_count,
        "branch_ref_blockers": branch_blockers,
        "branch_ref_warnings": branch_warnings,
        "restore_requested": restore_requested,
        "restore_ok": restore_ok,
        "blocker_count": len(blockers),
        "warning_count": len(warnings),
        "blockers": blockers,
        "warnings": warnings,
        "next_actions": next_actions,
    }


def away_finish_completion_gate(
    *,
    checkpoint: dict[str, Any],
    metadata_promotion: dict[str, Any],
    restore_readiness: dict[str, Any],
    promote_metadata: bool,
    verify_restore: bool,
) -> dict[str, Any]:
    checkpoint_gate = (
        checkpoint.get("checkpoint_gate", {})
        if isinstance(checkpoint.get("checkpoint_gate"), dict)
        else away_checkpoint_gate(checkpoint)
    )
    restore_payload = (
        restore_readiness.get("readiness", {})
        if isinstance(restore_readiness.get("readiness"), dict)
        else {}
    )
    metadata_ok = not promote_metadata or bool(metadata_promotion.get("ok"))
    restore_ok = not verify_restore or bool(restore_payload.get("ok"))
    blockers = []
    warnings = []
    next_actions = []

    if not bool(checkpoint_gate.get("ok")):
        blockers.append("final checkpoint gate did not pass")
        blockers.extend(str(item) for item in checkpoint_gate.get("blockers", []) if item)
        next_actions.append("fix checkpoint blockers before treating away development as finished")
    if not metadata_ok:
        blockers.append("metadata promotion was requested but did not complete cleanly")
        next_actions.append("inspect metadata_promotion and rerun with an approved metadata policy if needed")
    if not restore_ok:
        blockers.append("final restore-readiness verification did not pass")
        next_actions.append("inspect restore_readiness before handoff or cleanup")
    for item in checkpoint_gate.get("warnings", []):
        if item:
            warnings.append(str(item))
    if promote_metadata and not bool(metadata_promotion.get("published")):
        warnings.append("metadata promotion did not publish online; this is acceptable only when publish policy is none")
    if not blockers:
        next_actions.append("away finish is ready for returning-operator review")

    return {
        "ok": bool(checkpoint_gate.get("ok") and metadata_ok and restore_ok),
        "ready_for_return_review": bool(checkpoint_gate.get("ok") and metadata_ok and restore_ok),
        "checkpoint_ok": bool(checkpoint_gate.get("ok")),
        "checkpoint_gate": checkpoint_gate,
        "metadata_promotion_requested": bool(promote_metadata),
        "metadata_promotion_ok": metadata_ok,
        "restore_readiness_requested": bool(verify_restore),
        "restore_readiness_ok": restore_ok,
        "blocker_count": len(blockers),
        "warning_count": len(warnings),
        "blockers": blockers,
        "warnings": warnings,
        "next_actions": next_actions,
    }


