def build_project_away_checkpoint_payload(
    *,
    ops_root: Path,
    project_name: str,
    machine_id_arg: str,
    phase: str,
    label: str,
    backups_root: Path,
    snapshots_root_arg: str,
    artifact_uri: list[str],
    artifact_path: list[str],
    artifact_hash_max_mb: int,
    skip_runtime: bool,
    branch_policy: str,
    include_untracked_in_branch: bool,
    verify_restore: bool,
    restore_root: Path,
    restore_smoke: bool,
    restore_wip: bool,
    replace_restore_workspace: bool,
    yes: bool,
) -> dict[str, Any]:
    project = project_entry(ops_root, project_name)
    if project is None:
        raise RuntimeError(f"project not found: {project_name}")
    machine_id = normalize_machine_id(machine_id_arg, ops_root)
    if not machine_id:
        raise RuntimeError("Unable to resolve local machine id. Pass --machine-id explicitly.")
    project_id = str(project.get("project_id") or "")
    safe_phase = slugify(phase, "checkpoint")
    safe_label = slugify(label, "")
    checkpoint_label = f"away-{safe_phase}" + (f"-{safe_label}" if safe_label else "")
    checkpoint_snapshot_id = f"{time.strftime('%Y%m%d_%H%M%S')}_{machine_id}_{checkpoint_label}"
    backup_payload = build_project_backup_payload(
        ops_root=ops_root,
        project_name=project_id,
        machine_id_arg=machine_id,
        backups_root=backups_root,
        label=checkpoint_label,
        dry_run=False,
        snapshot_id_override=checkpoint_snapshot_id,
    )
    snapshot_payload = build_project_snapshot_payload(
        ops_root=ops_root,
        project_name=project_id,
        machine_id_arg=machine_id,
        label=checkpoint_label,
        artifact_uri=artifact_uri,
        artifact_path=artifact_path,
        validation_command=[f"python3 scripts/clutch_ctl.py project-status --project {project_id}"],
        snapshots_root_arg=snapshots_root_arg,
        artifact_hash_max_mb=artifact_hash_max_mb,
        write=True,
        backups_root=backups_root,
        skip_runtime=skip_runtime,
        snapshot_id_override=checkpoint_snapshot_id,
    )
    branch_checkpoints = []
    if branch_policy == "local":
        snapshot_id = str(snapshot_payload.get("snapshot_id") or "")
        ref_project = git_ref_slug(project_id, "project")
        ref_phase = git_ref_slug(safe_phase, "checkpoint")
        ref_snapshot = git_ref_slug(snapshot_id, "snapshot")
        for repo_source in project_repo_sources(project):
            repo_id = git_ref_slug(str(repo_source.get("repo_id") or "repo"), "repo")
            repo_path_text = repo_source_machine_path(repo_source, machine_id)
            branch_name = f"clutch-away/{ref_project}/{ref_phase}/{ref_snapshot}/{repo_id}"
            if not repo_path_text:
                branch_checkpoints.append(
                    {
                        "repo_id": repo_id,
                        "branch": branch_name,
                        "ref": f"refs/heads/{branch_name}",
                        "repo_path": "",
                        "status": "path_unmapped",
                        "details": "no machine-local path is configured for this repo source",
                    }
                )
                continue
            repo_path = Path(repo_path_text).expanduser()
            result = create_git_worktree_checkpoint_ref(
                repo_path=repo_path,
                branch_name=branch_name,
                message=(
                    f"CLUTCH away checkpoint {checkpoint_label}\n\n"
                    f"Project: {project_id}\n"
                    f"Phase: {safe_phase}\n"
                    f"Snapshot: {snapshot_id}\n"
                    "This is a machine-local checkpoint ref created without switching branches."
                ),
                include_untracked=include_untracked_in_branch,
            )
            result["repo_id"] = repo_id
            branch_checkpoints.append(result)
    restore_verification: dict[str, Any] = {"requested": False}
    if verify_restore:
        snapshot_id = str(snapshot_payload.get("snapshot_id") or "")
        restore_payload = build_project_restore_readiness_payload(
            ops_root=ops_root,
            project_name=project_id,
            machine_id_arg=machine_id,
            snapshot_id=snapshot_id,
            snapshots_root_arg=snapshots_root_arg,
            repo_id_filter="",
            metadata_branch="",
            metadata_branch_prefix="clutch-snapshots",
            metadata_subdir=".clutch/snapshots",
            backup_snapshot_id=snapshot_id,
            backups_root=backups_root,
            restore_root=restore_root,
            restore_smoke=restore_smoke,
            restore_wip=restore_wip,
            replace_restore_workspace=replace_restore_workspace,
            yes=yes,
        )
        restore_verification = {
            "requested": True,
            "readiness": compact_restore_readiness(restore_payload),
        }
    payload = {
        "schema": "clutch.project_away_checkpoint.v1",
        "project_id": project_id,
        "display_name": project.get("display_name"),
        "machine_id": machine_id,
        "phase": safe_phase,
        "label": checkpoint_label,
        "backup_snapshot_id": backup_payload.get("snapshot_id"),
        "backup_snapshot_root": backup_payload.get("snapshot_root"),
        "project_snapshot_id": snapshot_payload.get("snapshot_id"),
        "project_snapshot_manifest_path": snapshot_payload.get("manifest_path"),
        "artifact_pointers": snapshot_payload.get("artifact_pointers", [])
        if isinstance(snapshot_payload.get("artifact_pointers"), list)
        else [],
        "artifact_pointer_count": len(snapshot_payload.get("artifact_pointers", []))
        if isinstance(snapshot_payload.get("artifact_pointers"), list)
        else 0,
        "backup_repo_results": backup_payload.get("repo_results", []),
        "snapshot_repo_versions": snapshot_payload.get("repo_versions", []),
        "branch_policy": branch_policy,
        "branch_checkpoints": branch_checkpoints,
        "restore_verification": restore_verification,
        "checkpoint_policy": (
            "machine-local backup plus project-snapshot manifest"
            + (
                "; local clutch-away/* git checkpoint refs were written without online publication"
                if branch_policy == "local"
                else "; no branch write"
            )
        ),
    }
    checkpoint_gate = away_checkpoint_gate(payload)
    payload["checkpoint_gate"] = checkpoint_gate
    payload["ok"] = bool(checkpoint_gate.get("ok"))
    local_files = ensure_local_project_files(
        machine_id=machine_id,
        project_id=project_id,
        display_name=str(project.get("display_name") or project_id),
        create=True,
    )
    checkpoint_log_path = project_away_checkpoint_log_path(local_files)
    append_jsonl(checkpoint_log_path, compact_away_checkpoint_event(payload))
    payload["checkpoint_log_path"] = str(checkpoint_log_path)
    payload["checkpoint_logged"] = True
    return payload


def build_project_away_finish_payload(
    *,
    ops_root: Path,
    project_name: str,
    machine_id_arg: str,
    label: str,
    backups_root: Path,
    snapshots_root_arg: str,
    artifact_uri: list[str],
    artifact_path: list[str],
    artifact_hash_max_mb: int,
    skip_runtime: bool,
    branch_policy: str,
    include_untracked_in_branch: bool,
    verify_restore: bool,
    restore_root: Path,
    restore_smoke: bool,
    restore_wip: bool,
    replace_restore_workspace: bool,
    promote_metadata: bool,
    metadata_repo_id: str,
    metadata_subdir: str,
    metadata_branch_prefix: str,
    metadata_commit_policy: str,
    metadata_publish_policy: str,
    allow_dirty_metadata_target: bool,
    yes: bool,
) -> dict[str, Any]:
    project = project_entry(ops_root, project_name)
    if project is None:
        raise RuntimeError(f"project not found: {project_name}")
    project_id = str(project.get("project_id") or "")
    checkpoint = build_project_away_checkpoint_payload(
        ops_root=ops_root,
        project_name=project_id,
        machine_id_arg=machine_id_arg,
        phase="final",
        label=label or "finish",
        backups_root=backups_root,
        snapshots_root_arg=snapshots_root_arg,
        artifact_uri=artifact_uri,
        artifact_path=artifact_path,
        artifact_hash_max_mb=artifact_hash_max_mb,
        skip_runtime=skip_runtime,
        branch_policy=branch_policy,
        include_untracked_in_branch=include_untracked_in_branch,
        verify_restore=False,
        restore_root=restore_root,
        restore_smoke=False,
        restore_wip=False,
        replace_restore_workspace=False,
        yes=yes,
    )
    snapshot_id = str(checkpoint.get("project_snapshot_id") or "")
    backup_snapshot_id = str(checkpoint.get("backup_snapshot_id") or snapshot_id)
    machine_id = str(checkpoint.get("machine_id") or normalize_machine_id(machine_id_arg, ops_root))

    metadata_promotion: dict[str, Any] = {"requested": False}
    if promote_metadata:
        if not str(metadata_repo_id or "").strip():
            raise RuntimeError("--metadata-repo-id is required when --promote-metadata is used")
        promotion_payload = build_project_snapshot_promote_payload(
            ops_root=ops_root,
            project_name=project_id,
            machine_id_arg=machine_id,
            snapshot_id=snapshot_id,
            snapshots_root_arg=snapshots_root_arg,
            repo_id=metadata_repo_id,
            metadata_subdir=metadata_subdir,
            commit_policy=metadata_commit_policy,
            metadata_branch_prefix=metadata_branch_prefix,
            publish_policy=metadata_publish_policy,
            write=True,
            yes=yes,
            allow_dirty_target=allow_dirty_metadata_target,
            allow_non_main_publisher=False,
        )
        publication = (
            promotion_payload.get("publication", {})
            if isinstance(promotion_payload.get("publication"), dict)
            else {}
        )
        publish_ok = (
            metadata_publish_policy == "none"
            or (publication.get("status") == "pushed" and bool(publication.get("pushed")))
        )
        metadata_promotion = {
            "requested": True,
            "ok": bool(promotion_payload.get("wrote")) and publish_ok,
            "status": str(promotion_payload.get("status") or ""),
            "metadata_branch": str(promotion_payload.get("metadata_branch") or ""),
            "metadata_commit_short": str(
                (
                    promotion_payload.get("branch_result", {})
                    if isinstance(promotion_payload.get("branch_result"), dict)
                    else {}
                ).get("commit", "")
            )[:7],
            "publish_policy": metadata_publish_policy,
            "publication_status": str(publication.get("status") or ""),
            "published": bool(publication.get("pushed")),
            "details": str(promotion_payload.get("details") or ""),
        }

    restore_readiness: dict[str, Any] = {"requested": False}
    if verify_restore:
        restore_payload = build_project_restore_readiness_payload(
            ops_root=ops_root,
            project_name=project_id,
            machine_id_arg=machine_id,
            snapshot_id=snapshot_id,
            snapshots_root_arg=snapshots_root_arg,
            repo_id_filter=metadata_repo_id if promote_metadata else "",
            metadata_branch="",
            metadata_branch_prefix=metadata_branch_prefix,
            metadata_subdir=metadata_subdir,
            backup_snapshot_id=backup_snapshot_id,
            backups_root=backups_root,
            restore_root=restore_root,
            restore_smoke=restore_smoke,
            restore_wip=restore_wip,
            replace_restore_workspace=replace_restore_workspace,
            yes=yes,
        )
        restore_readiness = {
            "requested": True,
            "readiness": compact_restore_readiness(restore_payload),
        }

    completion_gate = away_finish_completion_gate(
        checkpoint=checkpoint,
        metadata_promotion=metadata_promotion,
        restore_readiness=restore_readiness,
        promote_metadata=promote_metadata,
        verify_restore=verify_restore,
    )
    payload = {
        "schema": "clutch.project_away_finish.v1",
        "project_id": project_id,
        "display_name": project.get("display_name"),
        "machine_id": machine_id,
        "label": checkpoint.get("label"),
        "snapshot_id": snapshot_id,
        "backup_snapshot_id": backup_snapshot_id,
        "checkpoint": checkpoint,
        "metadata_promotion": metadata_promotion,
        "restore_readiness": restore_readiness,
        "completion_gate": completion_gate,
        "ok": bool(snapshot_id and backup_snapshot_id and completion_gate.get("ok")),
    }
    local_files = ensure_local_project_files(
        machine_id=machine_id,
        project_id=project_id,
        display_name=str(project.get("display_name") or project_id),
        create=True,
    )
    finish_log_path = project_away_checkpoint_log_path(local_files)
    append_jsonl(finish_log_path, compact_away_finish_event(payload))
    payload["finish_log_path"] = str(finish_log_path)
    payload["finish_logged"] = True
    return payload


def is_away_snapshot_item(item: dict[str, Any]) -> bool:
    snapshot_id = str(item.get("snapshot_id") or "")
    label = str(item.get("label") or "")
    branch = str(item.get("branch") or "")
    ref_name = str(item.get("ref") or "")
    return any(
        AWAY_SNAPSHOT_MARKER_RE.search(value)
        for value in (snapshot_id, label, branch, ref_name)
    )


def limited_away_items(items: list[dict[str, Any]], limit: int) -> list[dict[str, Any]]:
    filtered = [item for item in items if isinstance(item, dict) and is_away_snapshot_item(item)]
    safe_limit = max(int(limit), 0)
    return filtered[:safe_limit] if safe_limit else filtered


def flatten_snapshot_metadata_items(payload: dict[str, Any]) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for repo_result in payload.get("repo_results", []):
        if not isinstance(repo_result, dict):
            continue
        repo_id = str(repo_result.get("repo_id") or "")
        for item in repo_result.get("items", []):
            if not isinstance(item, dict):
                continue
            compact = dict(item)
            compact.setdefault("repo_id", repo_id)
            items.append(compact)
    items.sort(key=lambda item: str(item.get("committer_date") or item.get("created_at_local") or ""), reverse=True)
    return items


def compact_away_report_backup_item(item: dict[str, Any]) -> dict[str, Any]:
    repo_results = item.get("repo_results", []) if isinstance(item.get("repo_results"), list) else []
    repo_heads = {
        str(repo.get("repo_id") or ""): str(repo.get("head") or "")
        for repo in repo_results
        if isinstance(repo, dict) and str(repo.get("repo_id") or "")
    }
    repo_dirty = {
        str(repo.get("repo_id") or ""): bool(repo.get("dirty"))
        for repo in repo_results
        if isinstance(repo, dict) and str(repo.get("repo_id") or "")
    }
    return {
        "snapshot_id": str(item.get("snapshot_id") or ""),
        "project_id": str(item.get("project_id") or ""),
        "machine_id": str(item.get("machine_id") or ""),
        "created_at_local": str(item.get("created_at_local") or ""),
        "mtime_local": str(item.get("mtime_local") or ""),
        "manifest_path": str(item.get("manifest_path") or ""),
        "snapshot_root": str(item.get("snapshot_root") or ""),
        "file_count": int(item.get("file_count") or 0),
        "repo_count": int(item.get("repo_count") or len(repo_results)),
        "dirty_repo_count": sum(1 for dirty in repo_dirty.values() if dirty),
        "repo_heads": repo_heads,
        "repo_dirty_by_id": repo_dirty,
        "dry_run": bool(item.get("dry_run")),
    }


