SELF_TEST_OUTPUT_MAX_CHARS = 1200
SELF_TEST_HEALTH_ADVISORY_FAILURES = {
    "project_status_clutch": {
        "returncodes": {1, 2},
        "markers": ("status_ok=False", "attention kind=repo_sync severity=warning"),
        "reason": "project status smoke surfaced dirty or attention state instead of a command failure",
    },
    "away_cycles_read": {
        "returncodes": {2},
        "markers": ("soak_status=no_cycles", "valid_cycle_count=0"),
        "reason": "no away development cycle history exists yet",
    },
    "away_cycle_no_record": {
        "returncodes": {2},
        "markers": ("stop_reason=missing_away_plan",),
        "reason": "queued away-cycle probe is blocked because no away plan is active",
    },
    "away_report_read": {
        "returncodes": {2},
        "markers": ("stop_reason=missing_away_plan", "away_plan_present=False"),
        "reason": "away report is blocked because no away plan is active",
    },
    "overview_skip_runtime": {
        "returncodes": {1, 2},
        "markers": ("overview_ok=False", "attention kind="),
        "reason": "overview smoke surfaced project attention state instead of a command failure",
    },
    "pre_web_readiness_skip_runtime": {
        "returncodes": {1, 2},
        "markers": ("command_role=clutch_self_development_milestone_gate", "pre_web_readiness_ok=False"),
        "reason": "CLUTCH self-development milestone gate is not clean yet",
    },
}


def compact_self_test_output(
    output: str,
    *,
    max_chars: int = SELF_TEST_OUTPUT_MAX_CHARS,
) -> tuple[str, bool, int]:
    stripped = (output or "").strip()
    original_char_count = len(stripped)
    max_output_chars = max(int(max_chars), 128)
    if original_char_count <= max_output_chars:
        return stripped, False, original_char_count

    marker = f"\n... self-test output truncated ({original_char_count} chars total) ...\n"
    keep_chars = max(max_output_chars - len(marker), 32)
    head_chars = keep_chars // 2
    tail_chars = keep_chars - head_chars
    compacted = f"{stripped[:head_chars]}{marker}{stripped[-tail_chars:]}"
    return compacted, True, original_char_count


def run_self_test_step(name: str, command: list[str], *, cwd: Path, timeout_sec: int) -> dict[str, Any]:
    started = time.time()
    timeout = max(int(timeout_sec), 1)
    try:
        result = subprocess.run(
            command,
            cwd=str(cwd),
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            check=False,
            timeout=timeout,
        )
        output = result.stdout or ""
        output_char_count = len((output or "").strip())
        ok = result.returncode == 0
        if ok:
            compacted_output = ""
            output_truncated = False
            output_suppressed = output_char_count > 0
        else:
            compacted_output, output_truncated, output_char_count = compact_self_test_output(output)
            output_suppressed = False
        return {
            "name": name,
            "command": command_line(command),
            "returncode": int(result.returncode),
            "duration_sec": round(time.time() - started, 3),
            "timeout_sec": timeout,
            "timed_out": False,
            "output": compacted_output,
            "output_char_count": output_char_count,
            "output_suppressed": output_suppressed,
            "output_truncated": output_truncated,
            "command_ok": ok,
            "advisory": False,
            "advisory_reason": "",
            "ok": ok,
        }
    except subprocess.TimeoutExpired as exc:
        if isinstance(exc.stdout, bytes):
            stdout = exc.stdout.decode(errors="replace")
        else:
            stdout = exc.stdout if isinstance(exc.stdout, str) else ""
        compacted_output, output_truncated, output_char_count = compact_self_test_output(
            f"{stdout}\nself-test step timed out"
        )
        return {
            "name": name,
            "command": command_line(command),
            "returncode": 124,
            "duration_sec": round(time.time() - started, 3),
            "timeout_sec": timeout,
            "timed_out": True,
            "output": compacted_output,
            "output_char_count": output_char_count,
            "output_suppressed": False,
            "output_truncated": output_truncated,
            "command_ok": False,
            "advisory": False,
            "advisory_reason": "",
            "ok": False,
        }


def self_test_health_advisory_reason(name: str, step: dict[str, Any]) -> str:
    policy = SELF_TEST_HEALTH_ADVISORY_FAILURES.get(name)
    if not policy:
        return ""
    if bool(step.get("timed_out")):
        return ""
    try:
        returncode = int(step.get("returncode") or 0)
    except (TypeError, ValueError):
        return ""
    if returncode not in set(policy.get("returncodes") or []):
        return ""
    output = str(step.get("output") or "")
    if "Traceback (most recent call last)" in output:
        return ""
    markers = tuple(str(item) for item in policy.get("markers", ()) if str(item))
    if markers and not any(marker in output for marker in markers):
        return ""
    return str(policy.get("reason") or "")


def normalize_self_test_health_step(
    name: str,
    step: dict[str, Any],
    *,
    strict_health_checks: bool,
) -> dict[str, Any]:
    normalized = dict(step)
    normalized.setdefault("command_ok", bool(normalized.get("ok")))
    normalized.setdefault("advisory", False)
    normalized.setdefault("advisory_reason", "")
    normalized["advisory_allowed"] = name in SELF_TEST_HEALTH_ADVISORY_FAILURES
    if strict_health_checks:
        return normalized
    if bool(normalized.get("ok")):
        return normalized
    reason = self_test_health_advisory_reason(name, normalized)
    if not reason:
        return normalized
    normalized["ok"] = True
    normalized["advisory"] = True
    normalized["advisory_reason"] = reason
    return normalized


def build_self_test_payload(
    *,
    include_diff_check: bool,
    include_health_checks: bool,
    strict_health_checks: bool,
    include_restore_checks: bool,
    step_timeout_sec: int,
) -> dict[str, Any]:
    timeout = max(int(step_timeout_sec), 1)
    steps = [
        run_self_test_step(
            "py_compile",
            [
                sys.executable,
                "-m",
                "py_compile",
                *self_test_py_compile_targets(),
            ],
            cwd=ROOT_DIR,
            timeout_sec=timeout,
        ),
        run_self_test_step(
            "unittest_discover",
            [sys.executable, "-m", "unittest", "discover", "-s", "tests"],
            cwd=ROOT_DIR,
            timeout_sec=timeout,
        ),
    ]
    steps.extend(
        run_self_test_step(name, command, cwd=ROOT_DIR, timeout_sec=timeout)
        for name, command in self_test_cli_smoke_commands()
    )
    if include_health_checks:
        for name, command in self_test_health_check_commands():
            step = run_self_test_step(name, command, cwd=ROOT_DIR, timeout_sec=timeout)
            steps.append(
                normalize_self_test_health_step(
                    name,
                    step,
                    strict_health_checks=bool(strict_health_checks),
                )
            )
    if include_restore_checks:
        steps.extend(
            run_self_test_step(name, command, cwd=ROOT_DIR, timeout_sec=timeout)
            for name, command in self_test_restore_check_commands()
        )
    if include_diff_check:
        steps.append(
            run_self_test_step(
                "git_diff_check",
                ["git", "diff", "--check"],
                cwd=ROOT_DIR,
                timeout_sec=timeout,
            )
        )
    failed_steps = [item for item in steps if not item["ok"]]
    command_failed_steps = [
        item
        for item in steps
        if not bool(item.get("command_ok", item.get("returncode") == 0))
    ]
    advisory_steps = [item for item in steps if item.get("advisory")]
    passed_steps = [item for item in steps if item["ok"]]
    return {
        "schema": "clutch.self_test.v1",
        "root": str(ROOT_DIR),
        "read_only": True,
        "diff_check_included": include_diff_check,
        "health_checks_included": include_health_checks,
        "strict_health_checks": bool(strict_health_checks),
        "restore_checks_included": include_restore_checks,
        "step_timeout_sec": timeout,
        "step_count": len(steps),
        "passed_step_count": len(passed_steps),
        "failed_step_count": len(failed_steps),
        "command_failed_step_count": len(command_failed_steps),
        "advisory_step_count": len(advisory_steps),
        "advisory_nonzero_step_count": len(advisory_steps),
        "timed_out_step_count": sum(1 for item in steps if item.get("timed_out")),
        "suppressed_output_step_count": sum(1 for item in steps if item.get("output_suppressed")),
        "truncated_output_step_count": sum(1 for item in steps if item.get("output_truncated")),
        "steps": steps,
        "ok": not failed_steps,
    }


def existing_binding_for_thread(
    *,
    project_id: str,
    role: str,
    machine_id: str | None,
    thread_id: str | None,
) -> dict[str, Any] | None:
    if not project_id or not role or not thread_id:
        return None
    for item in active_bindings_for_project(project_id):
        if item.get("thread_id") != thread_id:
            continue
        if item.get("role") != role:
            continue
        if machine_id and item.get("machine_id") != machine_id:
            continue
        return item
    return None


def existing_project_binding_for_thread(
    *,
    project_id: str,
    machine_id: str | None,
    thread_id: str | None,
) -> dict[str, Any] | None:
    if not project_id or not thread_id:
        return None
    role_rank = {"main": 0, "worker": 1, "observer": 2}
    candidates = []
    for item in active_bindings_for_project(project_id):
        if item.get("thread_id") != thread_id:
            continue
        if machine_id and item.get("machine_id") != machine_id:
            continue
        candidates.append(item)
    candidates.sort(key=lambda item: role_rank.get(str(item.get("role") or ""), 99))
    return candidates[0] if candidates else None


def active_bindings_for_thread(machine_id: str | None, thread_id: str | None) -> list[dict[str, Any]]:
    if not machine_id or not thread_id:
        return []
    role_rank = {"main": 0, "worker": 1, "observer": 2}

    def binding_time(item: dict[str, Any], key: str) -> int:
        try:
            return int(item.get(key) or 0)
        except (TypeError, ValueError):
            return 0

    bindings = [
        item
        for item in active_bindings_for_machine(machine_id)
        if item.get("thread_id") == thread_id
    ]
    bindings.sort(
        key=lambda item: (
            -binding_time(item, "updated_time_ns"),
            -binding_time(item, "created_time_ns"),
            role_rank.get(str(item.get("role") or ""), 99),
            str(item.get("project_id") or ""),
            str(item.get("binding_id") or ""),
        )
    )
    return bindings


def resolve_session_workspace(
    project: dict[str, Any],
    cwd: Path,
    machine_id: str | None,
    *,
    fallback_home: Path | None = None,
) -> str:
    if find_project_for_path([project], str(cwd)) is not None:
        return resolve_workspace_for_machine(
            project,
            str(cwd),
            machine_id,
            fallback_home=fallback_home,
        )
    default_workspace = machine_workspace_for_project(project, machine_id)
    if default_workspace:
        return default_workspace
    return resolve_workspace_for_machine(
        project,
        str(cwd),
        machine_id,
        fallback_home=fallback_home,
    )


def resolve_session_bind_role(
    *,
    project: dict[str, Any],
    requested_role: str,
    machine_id: str | None,
    thread_id: str | None,
) -> tuple[str, str, dict[str, Any] | None]:
    requested = str(requested_role or "auto").strip().lower()
    if requested in {"main", "worker", "observer"}:
        return requested, "explicit", None
    project_id = str(project.get("project_id") or "")
    existing = existing_project_binding_for_thread(
        project_id=project_id,
        machine_id=machine_id,
        thread_id=thread_id,
    )
    if existing is not None:
        role = str(existing.get("role") or "observer")
        if role in {"main", "worker", "observer"}:
            return role, "existing_thread_binding", existing
    roles = project_machine_role_summary(project)
    role_by_machine = roles.get("role_by_machine") if isinstance(roles.get("role_by_machine"), dict) else {}
    configured_role = str(role_by_machine.get(machine_id or "") or "")
    if configured_role in {"main", "worker", "observer"}:
        return configured_role, "project_machine_role", None
    return "observer", "fallback_observer", None


def session_binding_workspace_visibility(
    *,
    binding: Any,
    resolved_workspace: str,
) -> dict[str, Any]:
    if not isinstance(binding, dict) or not binding:
        return {
            "binding_workspace_path": "",
            "binding_workspace_matches_resolved": None,
            "binding_workspace_status": "no_binding",
        }

    binding_workspace = str(binding.get("workspace_path") or "")
    resolved = str(resolved_workspace or "")
    if binding_workspace and resolved:
        matches = binding_workspace == resolved
        status = "aligned" if matches else "mismatch"
    elif binding_workspace:
        matches = None
        status = "no_resolved_workspace"
    else:
        matches = None
        status = "missing"
    return {
        "binding_workspace_path": binding_workspace,
        "binding_workspace_matches_resolved": matches,
        "binding_workspace_status": status,
    }


def _active_bindings_from_payload(payload: dict[str, Any], machine_id: str | None) -> list[dict[str, Any]]:
    if not machine_id:
        return []
    bindings = payload.get("bindings", [])
    result: list[dict[str, Any]] = []
    for item in bindings:
        if not isinstance(item, dict):
            continue
        if item.get("machine_id") != machine_id:
            continue
        if not is_binding_active(item):
            continue
        result.append(item)
    return result


def ensure_binding(
    *,
    machine_id: str,
    project_id: str,
    role: str,
    thread_id: str,
    workspace_path: str,
    operator: str,
    lease_minutes: int,
    takeover: bool,
) -> tuple[dict[str, Any], str]:
    payload = load_active_bindings()
    bindings = payload.setdefault("bindings", [])
    active = [item for item in bindings if isinstance(item, dict) and is_binding_active(item)]

    for item in active:
        if (
            item.get("thread_id") == thread_id
            and item.get("project_id") == project_id
            and item.get("role") == role
        ):
            return item, "existing"

    for item in bindings:
        if not isinstance(item, dict):
            continue
        if not is_binding_active(item):
            continue
        if item.get("thread_id") == thread_id and item.get("project_id") == project_id:
            item["status"] = "released"
            item["released_time_ns"] = now_ns()

    blocking = [
        item
        for item in bindings
        if isinstance(item, dict)
        and is_binding_active(item)
        and item.get("project_id") == project_id
        if item.get("thread_id") != thread_id and item.get("role") == "main"
    ]
    if role == "main" and blocking and not takeover:
        raise RuntimeError(
            "Main binding already exists for this project. Use binding-check first or pass --takeover explicitly."
        )
    if role == "main" and blocking and takeover:
        for item in bindings:
            if item.get("binding_id") in {row.get("binding_id") for row in blocking}:
                item["status"] = "released"
                item["released_time_ns"] = now_ns()

    binding = {
        "binding_id": make_binding_id(machine_id, project_id, role),
        "machine_id": machine_id,
        "project_id": project_id,
        "role": role,
        "thread_id": thread_id,
        "workspace_path": workspace_path,
        "operator": operator,
        "status": "active",
        "created_time_ns": now_ns(),
        "updated_time_ns": now_ns(),
        "lease_expires_ns": now_ns() + max(lease_minutes, 1) * 60 * 1_000_000_000,
        "source": "clutch_ctl",
    }
    bindings.append(binding)
    save_json(ACTIVE_BINDINGS_PATH, payload)
    return binding, "created"


def refresh_existing_binding(
    existing_binding: dict[str, Any],
    *,
    workspace_path: str,
    operator: str,
    lease_minutes: int,
) -> tuple[dict[str, Any], bool]:
    binding_id = str(existing_binding.get("binding_id") or "")
    if not binding_id:
        return existing_binding, False
    payload = load_active_bindings()
    bindings = payload.get("bindings", [])
    for item in bindings:
        if not isinstance(item, dict):
            continue
        if item.get("binding_id") != binding_id:
            continue
        if not is_binding_active(item):
            continue
        changed = False
        if workspace_path and item.get("workspace_path") != workspace_path:
            item["workspace_path"] = workspace_path
            changed = True
        if operator and item.get("operator") != operator:
            item["operator"] = operator
            changed = True
        lease_expires_ns = now_ns() + max(lease_minutes, 1) * 60 * 1_000_000_000
        try:
            current_lease_expires_ns = int(item.get("lease_expires_ns") or 0)
        except (TypeError, ValueError):
            current_lease_expires_ns = 0
        if lease_expires_ns > current_lease_expires_ns:
            item["lease_expires_ns"] = lease_expires_ns
            changed = True
        if changed:
            item["updated_time_ns"] = now_ns()
            save_json(ACTIVE_BINDINGS_PATH, payload)
        return dict(item), changed
    return existing_binding, False


