    print(f"machine_detach_reason={payload['machine_detach_reason'] or ''}")
    print(f"ops_root={payload['ops_root']}")
    print(f"notify_service={payload['notify_service']}")
    print(f"daemon_service={payload['daemon_service']}")
    print(f"legacy_notify_service={payload['legacy_notify_service']}")
