def cmd_overview(args: argparse.Namespace) -> int:
    payload = build_overview_payload(
        ops_root=Path(args.ops_root).expanduser(),
        project_filters=args.project,
        machine_id_arg=args.machine_id,
        backups_root=Path(args.backups_root).expanduser(),
        backup_limit=args.backup_limit,
        collab_stale_sec=max(int(args.collab_stale_sec), 1),
        hardware_limit=args.hardware_limit,
        include_runtime=not bool(args.skip_runtime),
        include_workers=not bool(args.skip_workers),
        include_hardware=not bool(args.skip_hardware),
    )
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 0 if payload["ok"] else 1

    print(f"overview_ok={payload['ok']}")
    print(f"machine_id={payload['machine_id'] or ''}")
    print(f"machine_display_name={payload['machine_display_name'] or ''}")
    lifecycle = payload.get("machine_lifecycle", {}) if isinstance(payload.get("machine_lifecycle"), dict) else {}
    print(
        f"machine_lifecycle_ok={lifecycle.get('ok')} "
        f"install_ready={lifecycle.get('install_ready')} "
        f"session_entry_ready={lifecycle.get('session_entry_ready')} "
        f"online_sync_ready={lifecycle.get('online_sync_ready')} "
        f"runtime_ready={lifecycle.get('runtime_ready')} "
        f"reconnect_ready={lifecycle.get('reconnect_ready')} "
        f"error_count={lifecycle.get('error_count')} "
        f"warning_count={lifecycle.get('warning_count')}"
    )
    runtime = payload["runtime"]
    if runtime["included"]:
        print(
            f"runtime_ok={runtime['ok']} "
            f"failed_required_count={runtime['failed_required_count']} "
            f"required_check_count={runtime['required_check_count']}"
        )
        for command in runtime["recovery_commands"]:
            print(f"runtime_recovery_command={command}")
    workers = payload["workers"]
    if workers["included"]:
        print(
            f"worker_count={workers['worker_count']} available_count={workers['available_count']} "
            f"busy_count={workers['busy_count']} stale_count={workers['stale_count']}"
        )
        for item in workers["items"]:
            print(
                f"worker host={item['host']} role={item['role']} activity={item['activity']} "
                f"peer={item['peer_host']} peer_status={item['peer_status']} "
                f"peer_age_sec={item['peer_age_sec']}"
            )
    projects = payload["projects"]
    print(f"project_count={projects['project_count']} project_ok_count={projects['ok_count']}")
    for item in projects["items"]:
        sync_summary = item.get("sync_summary", {}) if isinstance(item.get("sync_summary"), dict) else {}
        online_backup = item.get("online_backup", {}) if isinstance(item.get("online_backup"), dict) else {}
        versioning = item.get("versioning_readiness", {}) if isinstance(item.get("versioning_readiness"), dict) else {}
        bindings = item.get("bindings", {}) if isinstance(item.get("bindings"), dict) else {}
        away_cycles = item.get("away_cycles", {}) if isinstance(item.get("away_cycles"), dict) else {}
        away_cycle_summary = (
            away_cycles.get("summary_file", {})
            if isinstance(away_cycles.get("summary_file"), dict)
            else {}
        )
        print(
            f"project project_id={item['project_id']} ok={item['ok']} "
            f"required_sync_ready={sync_summary.get('all_required_sync_ready')} "
            f"required_blocked_count={sync_summary.get('required_blocked_count')} "
            f"backup_snapshot_count={item.get('backup_snapshot_count')} "
            f"online_unconfigured_count={online_backup.get('unconfigured_count')} "
            f"versioning_ok={versioning.get('ok')} "
            f"versioning_blocking_count={versioning.get('blocking_finding_count')} "
            f"away_cycle_latest_decision={away_cycles.get('latest_decision', '')} "
            f"away_cycle_count={away_cycles.get('valid_cycle_count', 0)} "
            f"away_cycle_soak_status={away_cycles.get('soak_status', '')} "
            f"away_cycle_soak_validation_level={away_cycles.get('soak_validation_level', '')} "
            f"away_cycle_extended_soak_met={away_cycles.get('extended_soak_target_met', False)} "
            f"away_cycle_continue_streak={away_cycles.get('continue_streak_count', 0)} "
            f"away_cycle_summary_sections={away_cycle_summary.get('section_count', 0)} "
            f"away_cycle_summary_aligned={away_cycle_summary.get('aligned_with_cycle_log', True)} "
            f"main_count={bindings.get('main_count')} worker_count={bindings.get('worker_count')}"
        )
    hardware = payload["hardware_status_results"]
    if hardware["included"]:
        print(
            f"hardware_status_result_count={hardware['result_count']} "
            f"completed_count={hardware['completed_count']} "
            f"pending_count={hardware['pending_count']} failed_count={hardware['failed_count']}"
        )
        for item in hardware["items"]:
            print(
                f"hardware_status hardware_id={item['hardware_id']} "
                f"request_id={item['request_id']} status={item['result_status'] or 'pending'} "
                f"returncode={item['returncode']}"
            )
    print(f"attention_count={payload['attention_count']}")
    for item in payload["attention_items"]:
        detail = f" project_id={item.get('project_id')}" if item.get("project_id") else ""
        status = f" status={item.get('status')}" if item.get("status") else ""
        print(
            f"attention kind={item.get('kind')} severity={item.get('severity')}{detail}{status} "
            f"message={item.get('message')}"
        )
    return 0 if payload["ok"] else 1


def cmd_self_test(args: argparse.Namespace) -> int:
    payload = build_self_test_payload(
        include_diff_check=not bool(args.skip_diff_check),
        include_health_checks=bool(args.include_health_checks),
        strict_health_checks=bool(args.strict_health_checks),
        include_restore_checks=bool(args.include_restore_checks),
        step_timeout_sec=max(int(args.step_timeout_sec), 1),
    )
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 0 if payload["ok"] else 1
    print(f"self_test_ok={payload['ok']}")
    print(f"read_only={payload['read_only']}")
    print(f"diff_check_included={payload['diff_check_included']}")
    print(f"health_checks_included={payload['health_checks_included']}")
    print(f"strict_health_checks={payload['strict_health_checks']}")
    print(f"restore_checks_included={payload['restore_checks_included']}")
    print(f"step_timeout_sec={payload['step_timeout_sec']}")
    print(f"step_count={payload['step_count']}")
    print(f"failed_step_count={payload['failed_step_count']}")
    print(f"command_failed_step_count={payload['command_failed_step_count']}")
    print(f"advisory_nonzero_step_count={payload['advisory_nonzero_step_count']}")
    for item in payload["steps"]:
        print(
            f"step name={item['name']} ok={item['ok']} "
            f"command_ok={item.get('command_ok', item['returncode'] == 0)} "
            f"returncode={item['returncode']} duration_sec={item['duration_sec']} "
            f"timed_out={item.get('timed_out', False)} "
            f"advisory={item.get('advisory', False)} "
            f"output_truncated={item.get('output_truncated', False)} "
            f"output_suppressed={item.get('output_suppressed', False)} "
            f"output_char_count={item.get('output_char_count', 0)}"
        )
        if item.get("advisory_reason"):
            print(f"step_advisory_reason {item['name']}={item['advisory_reason']}")
        print(f"step_command {item['name']}={item['command']}")
        output = str(item.get("output") or "")
        if output:
            for line in output.splitlines()[-8:]:
                print(f"step_output {item['name']}={line}")
    return 0 if payload["ok"] else 1


def cmd_worker_status(args: argparse.Namespace) -> int:
    payload = build_worker_status_payload(
        host_filter=args.host,
        collab_stale_sec=max(int(args.collab_stale_sec), 1),
    )
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 0
    print(f"worker_count={payload['worker_count']}")
    print(f"available_count={payload['available_count']}")
    print(f"busy_count={payload['busy_count']}")
    print(f"stale_count={payload['stale_count']}")
    for item in payload["workers"]:
        health = item.get("health") if isinstance(item.get("health"), dict) else {}
        peer = item.get("peer") if isinstance(item.get("peer"), dict) else {}
        print(
            f"worker host={item['host']} role={item['role']} activity={item['activity']} "
            f"queue_length={item['queue_length']} peer={peer.get('host', '')} "
            f"peer_status={health.get('peer_status', '')} peer_age_sec={health.get('peer_age_sec', '')}"
        )
        current_task = item.get("current_task") if isinstance(item.get("current_task"), dict) else {}
        peer_task = peer.get("current_task") if isinstance(peer.get("current_task"), dict) else {}
        if current_task:
            print(
                f"current_task request_id={current_task.get('request_id', '')} "
                f"project_id={current_task.get('project_id', '')} workspace_path={current_task.get('workspace_path', '')}"
            )
        if peer_task:
            print(
                f"peer_current_task request_id={peer_task.get('request_id', '')} "
                f"project_id={peer_task.get('project_id', '')} workspace_path={peer_task.get('workspace_path', '')}"
            )
        outgoing = item.get("last_outgoing_request", {})
        if outgoing.get("request_id"):
            print(
                f"last_outgoing_request request_id={outgoing['request_id']} "
                f"kind={outgoing['request_kind']} project_id={outgoing['project_id']} "
                f"workspace_path={outgoing['workspace_path']}"
            )
        peer_result = item.get("last_peer_result", {})
        if peer_result.get("request_id"):
            print(
                f"last_peer_result request_id={peer_result['request_id']} "
                f"status={peer_result['result_status']} returncode={peer_result['returncode']} "
                f"summary={peer_result['summary']}"
            )
    if not payload["workers"]:
        print("no_workers")
    return 0


