def cmd_runtime_check(args: argparse.Namespace) -> int:
    payload = build_runtime_check_payload(
        ops_root=Path(args.ops_root).expanduser(),
        machine_id_arg=args.machine_id,
        host_arg=args.host,
        collab_stale_sec=max(int(args.collab_stale_sec), 1),
    )
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 0 if payload["ok"] else 1

    print(f"machine_id={payload['machine_id'] or ''}")
    print(f"machine_display_name={payload['machine_display_name']}")
    print(f"host={payload['host']}")
    print(f"runtime_ok={payload['ok']}")
    print(f"required_check_count={payload['required_check_count']}")
    print(f"failed_required_count={payload['failed_required_count']}")
    for item in payload["checks"]:
        required = "required" if item.get("required") else "optional"
        ok = "ok" if item.get("ok") else "fail"
        details = str(item.get("details") or "")
        suffix = f" details={details}" if details else ""
        print(f"check {required} {ok} {item.get('name')} status={item.get('status')}{suffix}")
