def cmd_machine_lifecycle_readiness(args: argparse.Namespace) -> int:
    payload = build_machine_lifecycle_readiness_payload(
        ops_root=Path(args.ops_root).expanduser(),
        machine_id_arg=args.machine_id,
        host_arg=args.host,
        collab_stale_sec=max(int(args.collab_stale_sec), 1),
        include_runtime=not bool(args.skip_runtime),
    )
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 0 if payload["ok"] else 1

    print(f"machine_id={payload['machine_id'] or ''}")
    print(f"machine_display_name={payload['machine_display_name'] or ''}")
    print(f"read_only={payload['read_only']}")
    print(f"lifecycle_ok={payload['ok']}")
    print(f"install_ready={payload['install_ready']}")
    print(f"session_entry_ready={payload['session_entry_ready']}")
    print(f"online_sync_ready={payload['online_sync_ready']}")
    print(f"runtime_ready={payload['runtime_ready']}")
    print(f"reconnect_ready={payload['reconnect_ready']}")
    print(f"worker_lan_mirror_fallback_active_count={payload['worker_lan_mirror_fallback_active_count']}")
    print(f"check_count={payload['check_count']}")
    print(f"error_count={payload['error_count']}")
    print(f"warning_count={payload['warning_count']}")
    agent_scope = payload.get("agent_guidance_scope", {})
    if isinstance(agent_scope, dict) and agent_scope:
        print(
            f"agent_guidance_status={agent_scope.get('status')} "
            f"minimal_hook_ok={agent_scope.get('minimal_hook_ok')} "
            f"project_marker_hit_count={agent_scope.get('project_marker_hit_count')} "
            f"line_count={agent_scope.get('line_count')}"
        )
    for repo_name, repo in payload["repos"].items():
        print(
            f"repo repo_name={repo_name} ok={repo['ok']} "
            f"clean={repo.get('clean')} "
            f"head={repo['head_short']} remote_head={repo['remote_head'].get('head_short')} "
            f"lan_mirror_head={repo['lan_mirror_head'].get('head_short')} "
            f"remote_head_matches_local={repo['remote_head_matches_local']} dirty={repo['dirty']} "
            f"sync_source={repo.get('sync_source')} "
            f"worker_lan_mirror_fallback_active={repo.get('worker_lan_mirror_fallback_active')} "
            f"path={repo['path']}"
        )
    for check in payload["checks"]:
        if check["severity"] == "ok":
            continue
        print(
            f"check category={check['category']} name={check['name']} "
            f"severity={check['severity']} status={check['status']} details={check['details']}"
        )
    for key, command in payload["next_commands"].items():
        print(f"next_command {key}={command}")
    for item in payload["explicit_user_approval_required_for"]:
        print(f"explicit_user_approval_required_for={item}")
    return 0 if payload["ok"] else 1


