def cmd_web_console_status(args: argparse.Namespace) -> int:
    payload = build_web_console_status_payload(args.web_url, expected_version=args.expected_version)
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 0 if payload["ok"] else 1
    print(f"web_console_status={payload['status']}")
    print(f"web_console_ok={payload['ok']}")
    print(f"web_console_running={payload['running']}")
    print(f"web_console_ready={payload['ready']}")
    print(f"web_console_url={payload['url']}")
    print(f"web_console_process_count={payload['process_count']}")
    print(f"web_console_state_path={payload['state_path']}")
    print(f"web_console_log_path={payload['log_path']}")
    health = payload.get("health", {}) if isinstance(payload.get("health"), dict) else {}
    print(f"web_console_health_details={health.get('details')}")
    default_command_keys = compact_health_string_list(health.get("default_command_keys"))
    if default_command_keys:
        print(f"web_console_default_command_keys={','.join(default_command_keys)}")
    preview_only_default_command_keys = compact_health_string_list(health.get("preview_only_default_command_keys"))
    if preview_only_default_command_keys:
        print(f"web_console_preview_only_default_command_keys={','.join(preview_only_default_command_keys)}")
    attention_shortcuts = (
        health.get("attention_shortcuts", {})
        if isinstance(health.get("attention_shortcuts"), dict)
        else {}
    )
    kind_commands = (
        attention_shortcuts.get("kind_commands", {})
        if isinstance(attention_shortcuts.get("kind_commands"), dict)
        else {}
    )
    repo_sync_shortcuts = compact_health_string_list(kind_commands.get("repo_sync"))
    if repo_sync_shortcuts:
        print(f"web_console_repo_sync_shortcuts={','.join(repo_sync_shortcuts)}")
    for process in payload.get("processes", []):
        print(
            "web_console_process "
            f"pid={process.get('pid')} host={process.get('host')} port={process.get('port')}"
        )
    for action in payload["next_actions"]:
        print(f"next_action={action}")
    return 0 if payload["ok"] else 1


