def cmd_machine_version_state(args: argparse.Namespace) -> int:
    payload = build_machine_version_state_payload(
        ops_root=Path(args.ops_root).expanduser(),
        machine_id_arg=args.machine_id,
    )
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 0 if payload["ok"] else 1
    summary = payload["summary"]
    print(f"machine_id={payload['machine_id']}")
    print(f"ok={payload['ok']}")
    print(f"status={payload.get('status', '')}")
    print(f"state_ready={payload['state_ready']}")
    print(f"release_ready={payload.get('release_ready', False)}")
    print(f"operator_summary={payload.get('operator_summary', '')}")
    print(f"repo_count={summary['repo_count']}")
    print(f"clean_repo_count={summary['clean_repo_count']}")
    print(f"dirty_repo_count={summary['dirty_repo_count']}")
    print(f"missing_repo_count={summary['missing_repo_count']}")
    print(f"remote_mismatch_count={summary['remote_mismatch_count']}")
    print(f"attention_repo_count={summary['attention_repo_count']}")
    print(f"release_alignment_status={summary['release_alignment_status']}")
    common_tags = ",".join(summary.get("common_exact_tags") or [])
    print(f"common_exact_tags={common_tags}")
    for item in payload["repos"]:
        ahead_behind = item.get("ahead_behind", {}) if isinstance(item.get("ahead_behind"), dict) else {}
        exact_tags = ",".join(item.get("exact_tags") or [])
        print(
            "repo "
            f"name={item.get('repo_name')} "
            f"status={item.get('status')} "
            f"tone={item.get('operator_tone')} "
            f"branch={item.get('current_branch') or item.get('branch')} "
            f"head={item.get('head_short')} "
            f"dirty={item.get('dirty')} "
            f"ahead={ahead_behind.get('ahead')} "
            f"behind={ahead_behind.get('behind')} "
            f"tags={exact_tags} "
            f"path={item.get('path')}"
        )
    for action in payload["next_actions"]:
        print(f"next_action={action}")
    return 0 if payload["ok"] else 1


def cmd_bindings(args: argparse.Namespace) -> int:
    ops_root = Path(args.ops_root).expanduser()
