def cmd_bind(args: argparse.Namespace) -> int:
    ops_root = Path(args.ops_root).expanduser()
    machine_id = normalize_machine_id(args.machine_id, ops_root)
    if not machine_id:
        raise RuntimeError("Unable to resolve local machine id. Pass --machine-id explicitly.")
    thread_id = current_thread_id(args.thread_id)
    if not thread_id:
        raise RuntimeError("No CODEX_THREAD_ID found; pass --thread-id explicitly.")

    binding, action = ensure_binding(
        machine_id=machine_id,
        project_id=args.project,
        role=args.role,
        thread_id=thread_id,
        workspace_path=args.workspace,
        operator=args.operator,
        lease_minutes=args.lease_minutes,
        takeover=args.takeover,
    )
    if action == "existing":
        print(f"binding_exists={binding['binding_id']}")
        return 0
    print(f"binding_id={binding['binding_id']}")
    return 0


def cmd_release_binding(args: argparse.Namespace) -> int:
    thread_id = current_thread_id(args.thread_id)
    payload = load_active_bindings()
    bindings = payload.get("bindings", [])
    changed = False
    for item in bindings:
        if args.binding_id and item.get("binding_id") != args.binding_id:
            continue
        if not args.binding_id and thread_id and item.get("thread_id") != thread_id:
            continue
        if item.get("status") == "released":
            continue
        item["status"] = "released"
        item["released_time_ns"] = now_ns()
        changed = True
    if not changed:
        raise RuntimeError("No matching active binding found.")
    save_json(ACTIVE_BINDINGS_PATH, payload)
    print("binding_released=true")
    return 0


def cmd_binding_check(args: argparse.Namespace) -> int:
    ops_root = Path(args.ops_root).expanduser()
    machine_id = normalize_machine_id(args.machine_id, ops_root)
    thread_id = current_thread_id(args.thread_id)
    machine_active = active_bindings_for_machine(machine_id)
    project_active = active_bindings_for_project(args.project) if args.project else []
    active = project_active if args.project else machine_active
    current = [item for item in active if thread_id and item.get("thread_id") == thread_id]
    foreign = [item for item in active if not thread_id or item.get("thread_id") != thread_id]
    other_machine_projects = [
        item
        for item in machine_active
        if args.project and item.get("project_id") != args.project
    ]
    if args.project and any(item.get("project_id") == args.project for item in current):
        action = "already_bound"
        reason = "current_thread_already_bound_to_project"
    elif args.project and any(item.get("role") == "main" for item in foreign):
        action = "takeover_required"
        reason = "foreign_project_main_binding_exists"
    elif args.project and other_machine_projects:
        action = "confirm_required"
        reason = "machine_already_bound_to_other_project"
    elif not foreign:
        action = "available"
        reason = "no_foreign_active_bindings"
    elif any(item.get("role") == "main" for item in foreign):
        action = "confirm_required"
        reason = "foreign_machine_main_binding_exists"
    else:
        action = "attach_or_worker"
        reason = "worker_only_bindings_exist"
    payload = {
        "machine_id": machine_id,
        "thread_id": thread_id,
        "project_id": args.project or None,
        "action_recommended": action,
        "reason": reason,
        "active_bindings": active,
        "machine_active_bindings": machine_active,
        "project_active_bindings": project_active,
    }
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 0
    print(f"action_recommended={action}")
    print(f"reason={reason}")
    print(f"active_binding_count={len(active)}")
    return 0


