def cmd_hardware_status(args: argparse.Namespace) -> int:
    payload = build_hardware_status_payload(
        ops_root=Path(args.ops_root).expanduser(),
        hardware_id=args.hardware_id,
        machine_id_arg=args.machine_id,
        collab_repo_arg=args.collab_repo,
        host_arg=args.host,
    )
    if args.delegate:
        if not payload["can_delegate"]:
            payload["delegate_output"] = (
                "delegation unavailable; inspect local_access, local_workspace, project_id, and collab_ctl"
            )
            payload["delegate_returncode"] = 2
        else:
            result = subprocess.run(
                shlex.split(str(payload["delegate_command"])),
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                check=False,
            )
            payload["delegated"] = result.returncode == 0
            payload["delegate_returncode"] = result.returncode
            payload["delegate_output"] = (result.stdout or "").strip()
            payload["request_id"] = extract_request_id(payload["delegate_output"])
    elif args.request_id:
        payload["request_id"] = args.request_id

    if payload["request_id"] and (args.wait_sec > 0 or args.request_id):
        wait_status, result_payload = wait_hardware_status_result(
            str(payload["local_host"]),
            str(payload["request_id"]),
            wait_sec=args.wait_sec,
            poll_sec=args.poll_sec,
        )
        payload["result_wait_status"] = wait_status
        payload["result"] = result_payload
    elif payload["request_id"]:
        payload["result_wait_status"] = "not_waited"

    if payload["request_id"]:
        request_payload = {
            "request_id": payload["request_id"],
            "request_kind": "inspect",
            "project_id": str(payload["hardware_route"].get("project_id") or ""),
            "workspace_path": str(payload["hardware_route"].get("owner_workspace") or payload["local_workspace"] or ""),
            "approval_required": False,
            "task_text": payload["status_task_text"],
            "time_ns": now_ns(),
        }
        cache_record = hardware_status_result_record(
            host=str(payload["local_host"]),
            source="hardware-status",
            result_payload=payload["result"] if isinstance(payload.get("result"), dict) else None,
            request_payload=request_payload,
        )
        upsert_hardware_status_cache(cache_record)

    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        if args.delegate and payload.get("delegate_returncode") not in (0, None):
            return int(payload["delegate_returncode"])
        if args.wait_sec > 0 and payload.get("result_wait_status") != "completed":
            return 1
        return 0

    route = payload["hardware_route"]
    print(f"hardware_id={route['hardware_id']}")
    print(f"display_name={route['display_name']}")
    print(f"owner_machine_id={route['owner_machine_id']}")
    print(f"local_access={route['local_access']}")
    print(f"project_id={route['project_id']}")
    print(f"owner_workspace={route['owner_workspace']}")
    print(f"local_workspace={payload['local_workspace']}")
    print(f"can_delegate={payload['can_delegate']}")
    print(f"legacy_diagnostic={payload['legacy_diagnostic']}")
    print(f"scope_note={payload['scope_note']}")
    print(f"status_task_text={payload['status_task_text']}")
    if payload["delegate_command"]:
        print(f"delegate_command={payload['delegate_command']}")
    if payload["request_id"]:
        print(f"request_id={payload['request_id']}")
        print(f"result_wait_status={payload['result_wait_status']}")
    if payload["result"]:
        result_payload = payload["result"]
        print(f"result_status={result_payload.get('result_status')}")
        print(f"result_returncode={result_payload.get('returncode')}")
        print(f"result_duration_ms={result_payload.get('duration_ms')}")
        print(f"result_summary={result_payload.get('summary')}")
        if result_payload.get("suggested_next_action"):
            print(f"suggested_next_action={result_payload.get('suggested_next_action')}")
    if args.delegate:
        print(f"delegated={payload['delegated']}")
        print(f"delegate_returncode={payload['delegate_returncode']}")
        if payload["delegate_output"]:
            print(f"delegate_output={payload['delegate_output']}")
    if args.delegate and payload.get("delegate_returncode") not in (0, None):
        return int(payload["delegate_returncode"])
    if args.wait_sec > 0 and payload.get("result_wait_status") != "completed":
        return 1
    return 0


