def parse_machine_path_spec(spec: str) -> tuple[str, str]:
    if "=" not in spec:
        raise RuntimeError(f"expected MACHINE_ID=PATH, got: {spec}")
    machine_id, path_text = spec.split("=", 1)
    machine_id = machine_id.strip()
    path_text = path_text.strip()
    if not machine_id or not path_text:
        raise RuntimeError(f"expected non-empty MACHINE_ID=PATH, got: {spec}")
    return machine_id, path_text


def parse_repo_source_spec(spec: str, default_repo_id: str) -> tuple[str, str, str]:
    repo_part = ""
    machine_part = spec
    if ":" in spec and spec.split(":", 1)[0].strip():
        repo_part, machine_part = spec.split(":", 1)
    machine_id, path_text = parse_machine_path_spec(machine_part)
    repo_id = slugify(repo_part.strip() or default_repo_id, default_repo_id)
    return repo_id, machine_id, path_text


def append_unique_text(mapping: dict[str, list[str]], key: str, value: str) -> None:
    items = mapping.setdefault(key, [])
    if value not in items:
        items.append(value)


def default_project_repo_source(repo_id: str, display_name: str, required: bool) -> dict[str, Any]:
    return {
        "backup_mode": "git_bundle",
        "branch": "main",
        "display_name": display_name,
        "machine_paths": {},
        "online_branch": "main",
        "online_enablement": {
            "approval_note": "",
            "approved": False,
            "approved_at_local": "",
            "approved_by": "",
            "required": True,
        },
        "online_remote_name": "origin",
        "online_remote_url": "",
        "remote_enablement": {
            "approval_note": "",
            "approved": False,
            "approved_at_local": "",
            "approved_by": "",
            "required": False,
        },
        "remote_name": "origin",
        "remote_url": "",
        "repo_id": repo_id,
        "required": required,
        "sync_mode": "git",
    }


def apply_project_role_policy(
    project: dict[str, Any],
    *,
    role_policy: str,
    main_machine_ids: list[str],
    worker_machine_ids: list[str],
    observer_machine_ids: list[str],
    preferred_main_machine_ids: list[str],
    clear_existing_roles: bool,
) -> None:
    project["machine_role_policy"] = role_policy
    role_keys = (
        "machine_roles",
        "main_machine_ids",
        "worker_machine_ids",
        "observer_machine_ids",
        "preferred_main_machine_ids",
    )
    if role_policy == "none":
        for key in role_keys:
            project.pop(key, None)
        return

    if clear_existing_roles:
        for key in role_keys:
            project.pop(key, None)

    supplied_roles = bool(main_machine_ids or worker_machine_ids or observer_machine_ids)
    if supplied_roles:
        role_map: dict[str, str] = {}
        for machine_id in main_machine_ids:
            role_map[machine_id] = "main"
        for machine_id in worker_machine_ids:
            role_map[machine_id] = "worker"
        for machine_id in observer_machine_ids:
            role_map[machine_id] = "observer"
        project["machine_roles"] = role_map
        project["main_machine_ids"] = main_machine_ids
        project["worker_machine_ids"] = worker_machine_ids
        if observer_machine_ids:
            project["observer_machine_ids"] = observer_machine_ids
        else:
            project.pop("observer_machine_ids", None)

    if preferred_main_machine_ids:
        project["preferred_main_machine_ids"] = preferred_main_machine_ids


def cmd_project_create(args: argparse.Namespace) -> int:
    ops_root = Path(args.ops_root).expanduser()
    payload = load_registry_payload(ops_root, "projects.json")
    projects = payload.get("projects", [])
    if not isinstance(projects, list):
        raise RuntimeError("projects registry is malformed")

    project_id = slugify(args.project, "")
    if not project_id:
        raise RuntimeError("--project must produce a non-empty project id")
    payload_before = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    existing = next(
        (item for item in projects if isinstance(item, dict) and item.get("project_id") == project_id),
        None,
    )
    if existing is not None and not args.update:
        raise RuntimeError(f"project already exists: {project_id}; pass --update to modify it")

    project: dict[str, Any] = existing if existing is not None else {}
    project["project_id"] = project_id
    project["display_name"] = args.display_name or project.get("display_name") or project_id
    project["binding_policy"] = args.binding_policy

    machine_workspaces = (
        project.get("machine_workspaces", {}) if isinstance(project.get("machine_workspaces"), dict) else {}
    )
    machine_workspaces = {
        str(machine_id): [str(path) for path in paths if str(path).strip()]
        for machine_id, paths in machine_workspaces.items()
        if isinstance(paths, list)
    }
    for spec in args.machine_workspace:
        machine_id, path_text = parse_machine_path_spec(spec)
        append_unique_text(machine_workspaces, machine_id, path_text)
    if machine_workspaces:
        project["machine_workspaces"] = machine_workspaces

    role_main = dedupe_strings([str(item).strip() for item in args.main_machine if str(item).strip()])
    role_worker = dedupe_strings([str(item).strip() for item in args.worker_machine if str(item).strip()])
    role_observer = dedupe_strings([str(item).strip() for item in args.observer_machine if str(item).strip()])
    preferred_main = dedupe_strings([str(item).strip() for item in args.preferred_main_machine if str(item).strip()])
    apply_project_role_policy(
        project,
        role_policy=args.role_policy,
        main_machine_ids=role_main,
        worker_machine_ids=role_worker,
        observer_machine_ids=role_observer,
        preferred_main_machine_ids=preferred_main,
        clear_existing_roles=not bool(args.update),
    )

    participant_machine_ids = dedupe_strings(
        [str(item).strip() for item in args.participant_machine if str(item).strip()]
        + list(machine_workspaces.keys())
        + role_main
        + role_worker
        + role_observer
    )
    if participant_machine_ids:
        project["participant_machine_ids"] = participant_machine_ids
    owner_machine_ids = dedupe_strings(
        [str(item).strip() for item in args.owner_machine if str(item).strip()]
    ) or participant_machine_ids
    if owner_machine_ids:
        project["owner_machine_ids"] = owner_machine_ids
    online_publishers = dedupe_strings(
        [str(item).strip() for item in args.online_publisher_machine if str(item).strip()]
    )
    if online_publishers:
        project["online_publisher_machine_ids"] = online_publishers

    for list_key, values in (
        ("hardware_ids", args.hardware_id),
        ("start_docs", args.start_doc),
        ("memory_docs", args.memory_doc),
        ("reentry_order", args.reentry),
        ("primary_repos", args.primary_repo),
    ):
        items = dedupe_strings([str(item).strip() for item in values if str(item).strip()])
        if items:
            project[list_key] = items
    if not project.get("primary_repos") and machine_workspaces:
        first_paths = [paths[0] for paths in machine_workspaces.values() if paths]
        if first_paths:
            project["primary_repos"] = [first_paths[0]]
    if args.admin_guard_required is not None:
        project["admin_guard_required"] = bool(args.admin_guard_required)

    repo_sources = (
        project.get("repo_sources", []) if isinstance(project.get("repo_sources"), list) else []
    )
    repo_by_id = {
        str(item.get("repo_id") or ""): item
        for item in repo_sources
        if isinstance(item, dict) and str(item.get("repo_id") or "")
    }
    default_repo_id = f"{project_id}-workspace"
    for spec in args.repo_source:
        repo_id, machine_id, path_text = parse_repo_source_spec(spec, default_repo_id)
        repo = repo_by_id.setdefault(
            repo_id,
            default_project_repo_source(repo_id, f"{project['display_name']} workspace", args.repo_required),
        )
        machine_paths = repo.setdefault("machine_paths", {})
        if not isinstance(machine_paths, dict):
            machine_paths = {}
            repo["machine_paths"] = machine_paths
        machine_paths[machine_id] = path_text
        repo["required"] = bool(args.repo_required)
    if not repo_by_id and machine_workspaces:
        repo = default_project_repo_source(
            default_repo_id,
            f"{project['display_name']} workspace",
            args.repo_required,
        )
        repo["machine_paths"] = {
            machine_id: paths[0]
            for machine_id, paths in machine_workspaces.items()
            if paths
        }
        repo_by_id[default_repo_id] = repo
    if repo_by_id:
        project["repo_sources"] = list(repo_by_id.values())

    if existing is None:
        projects.append(project)
    payload["projects"] = projects
    payload_after = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    changed = payload_after != payload_before
    confirmation_required = bool(changed and not args.dry_run and not args.yes)
    saved = False
    if changed and not args.dry_run and not confirmation_required:
        payload["last_updated_kst"] = current_local_timestamp()
        save_registry_payload(ops_root, "projects.json", payload)
        saved = True

    result = {
        "schema": "clutch.project_create.v1",
        "project_id": project_id,
        "created": existing is None,
        "updated": existing is not None,
        "dry_run": bool(args.dry_run),
        "changed": changed,
        "saved": saved,
        "confirmation_required": confirmation_required,
        "project": project,
        "project_machine_roles": project_machine_role_summary(project),
    }
    if args.json:
        print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
        return 2 if confirmation_required else 0
    print(f"project_id={project_id}")
    print(f"changed={changed}")
    print(f"saved={saved}")
    print(f"confirmation_required={confirmation_required}")
    print(f"machine_role_policy={result['project_machine_roles'].get('machine_role_policy')}")
    print(f"role_summary={result['project_machine_roles'].get('summary')}")
    if confirmation_required:
        print("confirmation_command_hint=rerun with --yes after verifying the registry change")
        return 2
    return 0


def cmd_project_role_configure(args: argparse.Namespace) -> int:
    ops_root = Path(args.ops_root).expanduser()
    payload = load_registry_payload(ops_root, "projects.json")
    projects = payload.get("projects", [])
    if not isinstance(projects, list):
        raise RuntimeError("projects registry is malformed")
    target_project = project_entry(ops_root, args.project)
    if target_project is None:
        raise RuntimeError(f"project not found: {args.project}")
    project_id = str(target_project.get("project_id") or "")
    payload_before = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    selected = next(
        (item for item in projects if isinstance(item, dict) and item.get("project_id") == project_id),
        None,
    )
    if selected is None:
        raise RuntimeError(f"project not found in registry payload: {project_id}")

    participant_machine_ids = dedupe_strings(
        [str(item).strip() for item in args.participant_machine if str(item).strip()]
    )
    if participant_machine_ids:
        selected["participant_machine_ids"] = participant_machine_ids

    apply_project_role_policy(
        selected,
        role_policy=args.role_policy,
        main_machine_ids=dedupe_strings([str(item).strip() for item in args.main_machine if str(item).strip()]),
        worker_machine_ids=dedupe_strings([str(item).strip() for item in args.worker_machine if str(item).strip()]),
        observer_machine_ids=dedupe_strings([str(item).strip() for item in args.observer_machine if str(item).strip()]),
        preferred_main_machine_ids=dedupe_strings(
            [str(item).strip() for item in args.preferred_main_machine if str(item).strip()]
        ),
        clear_existing_roles=bool(args.clear_existing_roles or args.role_policy == "none"),
    )

    payload_after = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    changed = payload_after != payload_before
    confirmation_required = bool(changed and not args.dry_run and not args.yes)
    saved = False
    if changed and not args.dry_run and not confirmation_required:
        payload["last_updated_kst"] = current_local_timestamp()
        save_registry_payload(ops_root, "projects.json", payload)
        saved = True

    roles = project_machine_role_summary(selected)
    result = {
        "schema": "clutch.project_role_config.v1",
        "project_id": project_id,
        "dry_run": bool(args.dry_run),
        "changed": changed,
        "saved": saved,
        "confirmation_required": confirmation_required,
        "project_machine_roles": roles,
    }
    if args.json:
        print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
        return 2 if confirmation_required else 0
    print(f"project_id={project_id}")
    print(f"changed={changed}")
    print(f"saved={saved}")
    print(f"confirmation_required={confirmation_required}")
    print(f"machine_role_policy={roles.get('machine_role_policy')}")
    print(f"role_summary={roles.get('summary')}")
    if confirmation_required:
        print("confirmation_command_hint=rerun with --yes after verifying the role policy change")
        return 2
    return 0


def cmd_project(args: argparse.Namespace) -> int:
    ops_root = Path(args.ops_root).expanduser()
    payload = project_entry(ops_root, args.project)
    if payload is None:
        raise RuntimeError(f"project not found: {args.project}")
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 0
    print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
    return 0


def cmd_attention_resolution_plan(args: argparse.Namespace) -> int:
    payload = build_attention_resolution_plan_payload(
        ops_root=Path(args.ops_root).expanduser(),
        project_filters=args.project,
        machine_id_arg=args.machine_id,
        backups_root=Path(args.backups_root).expanduser(),
        backup_limit=args.backup_limit,
        include_runtime=not bool(args.skip_runtime),
        collab_stale_sec=max(int(args.collab_stale_sec), 1),
    )
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 0

    print(f"status={payload['status']}")
    print(f"machine_id={payload['machine_id']}")
    print(f"project_count={payload['project_count']}")
    print(f"attention_count={payload['attention_count']}")
    print(f"resolution_step_count={payload['resolution_step_count']}")
    print(f"approval_required_count={payload['approval_required_count']}")
    print(f"blocked_count={payload['blocked_count']}")
    for step in payload["steps"]:
        print(
            f"attention_resolution project={step['project_id']} "
            f"kind={step['kind']} severity={step['severity']} state={step['state']} "
            f"plan_type={step['plan_type']}"
        )
        if step.get("message"):
            print(f"  message={step['message']}")
        if step.get("operator_summary"):
            print(f"  summary={step['operator_summary']}")
        for command in step.get("safe_commands", []):
            print(f"  safe_command={command}")
        for command in step.get("approval_commands", []):
            print(f"  approval_command={command}")
        if step.get("approval_note"):
            print(f"  approval_note={step['approval_note']}")
    if not payload["steps"]:
        print("attention_resolution=clean")
    return 0


def cmd_attention_resolution_apply(args: argparse.Namespace) -> int:
    payload = build_attention_resolution_apply_payload(
        ops_root=Path(args.ops_root).expanduser(),
        project_filters=args.project,
        machine_id_arg=args.machine_id,
        backups_root=Path(args.backups_root).expanduser(),
        backup_limit=args.backup_limit,
        include_runtime=not bool(args.skip_runtime),
        collab_stale_sec=max(int(args.collab_stale_sec), 1),
        dry_run=bool(args.dry_run),
        yes=bool(args.yes),
        allow_online_publish=bool(args.allow_online_publish),
        allow_project_sync=bool(args.allow_project_sync),
        allow_binding_align=bool(args.allow_binding_align),
        allow_local_backup=bool(args.allow_local_backup),
    )
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 0 if payload["ok"] or payload["confirmation_required"] else 1

    print(f"status={payload['status']}")
    print(f"dry_run={payload['dry_run']}")
    print(f"confirmation_required={payload['confirmation_required']}")
    print(f"before_attention_count={payload['before_attention_count']}")
    print(f"after_attention_count={payload['after_attention_count']}")
    print(f"planned_command_count={payload['planned_command_count']}")
    print(f"applied_action_count={payload['applied_action_count']}")
    print(f"previewed_action_count={payload['previewed_action_count']}")
    print(f"skipped_count={payload['skipped_count']}")
    print(f"failed_count={payload['failed_count']}")
    print(f"apply_command_hint={payload['apply_command_hint']}")
    for item in payload["actions"]:
        print(
            f"attention_apply project={item.get('project_id')} kind={item.get('kind')} "
            f"status={item.get('status')} reason={item.get('reason')}"
        )
    for item in payload["skipped"]:
        print(
            f"attention_apply_skipped project={item.get('project_id')} kind={item.get('kind')} "
            f"reason={item.get('reason')}"
        )
    for item in payload["failed"]:
        print(
            f"attention_apply_failed project={item.get('project_id')} kind={item.get('kind')} "
            f"returncode={item.get('returncode')} command={item.get('command')}"
        )
    return 0 if payload["ok"] or payload["confirmation_required"] else 1


def cmd_project_status(args: argparse.Namespace) -> int:
    payload = build_project_status_payload(
        ops_root=Path(args.ops_root).expanduser(),
        project_name=args.project,
        machine_id_arg=args.machine_id,
        backups_root=Path(args.backups_root).expanduser(),
        backup_limit=args.backup_limit,
        include_runtime=not bool(args.skip_runtime),
        collab_stale_sec=max(int(args.collab_stale_sec), 1),
    )
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
