    print(f"staged_count={summary['staged_count']}")
    print(f"would_stage_count={summary['would_stage_count']}")
    print(f"failed_count={summary['failed_count']}")
    print(f"warning_count={summary['warning_count']}")
    for item in payload["results"]:
        print(
            "artifact "
            f"status={item['status']} "
            f"source={item['source_path']} "
            f"target={item['target_path']} "
            f"uri={item['uri']}"
        )
        if item.get("warning"):
            print(f"artifact_warning={item['warning']}")
        if item.get("details"):
            print(f"artifact_details={item['details']}")
    if payload.get("confirmation_required"):
        return 2
    return 0 if payload.get("ok") else 1


