    soak = payload.get("soak", {}) if isinstance(payload.get("soak"), dict) else {}
    if soak:
        print(f"soak_status={soak.get('status', '')}")
        print(f"soak_validation_level={soak.get('validation_level', soak.get('status', ''))}")
        print(f"soak_target_met={bool(soak.get('target_met'))}")
        print(f"extended_soak_target_met={bool(soak.get('extended_target_met'))}")
        print(f"extended_soak_target_cycles={soak.get('extended_target_cycles', DEFAULT_AWAY_EXTENDED_SOAK_TARGET_CYCLES)}")
        print(f"extended_soak_target_minutes={soak.get('extended_target_minutes', DEFAULT_AWAY_EXTENDED_SOAK_TARGET_MINUTES)}")
        print(f"continue_streak_count={soak.get('continue_streak_count', 0)}")
        if soak.get("streak_elapsed_minutes") is not None:
            print(f"streak_elapsed_minutes={soak.get('streak_elapsed_minutes')}")
    print(f"soak_source={payload.get('soak_source', '')}")
    print(
        "soak_projection_includes_current_entry="
        f"{bool(payload.get('soak_projection_includes_current_entry', False))}"
    )
    print(f"cycle_log_valid_count_before_current={payload.get('cycle_log_valid_count_before_current', 0)}")
    print(f"cycle_log_projected_valid_count={payload.get('cycle_log_projected_valid_count', 0)}")
    print(f"cycle_log_recorded_valid_count={payload.get('cycle_log_recorded_valid_count', 0)}")
    print(f"recorded={payload['recorded']}")
    print(f"cycle_log_path={payload['cycle_log_path']}")
    print(f"cycle_summary_path={payload['cycle_summary_path']}")
    summary_file = (
        payload.get("summary_file", {})
        if isinstance(payload.get("summary_file"), dict)
        else {}
    )
    print(f"cycle_summary_present={bool(summary_file.get('present'))}")
    print(f"cycle_summary_section_count={summary_file.get('section_count', 0)}")
    print(f"cycle_summary_expected_section_count={summary_file.get('expected_section_count', 0)}")
    print(
        "cycle_summary_section_count_matches_valid_cycle_count="
        f"{bool(summary_file.get('section_count_matches_valid_cycle_count', True))}"
    )
    print(
        "cycle_summary_latest_heading_matches_latest_cycle="
        f"{bool(summary_file.get('latest_heading_matches_latest_cycle', True))}"
    )
    print(f"cycle_summary_aligned_with_log={bool(summary_file.get('aligned_with_cycle_log', True))}")
    if summary_file.get("latest_heading"):
        print(f"cycle_summary_latest_heading={summary_file.get('latest_heading')}")
    if summary_file.get("expected_latest_heading"):
        print(f"cycle_summary_expected_latest_heading={summary_file.get('expected_latest_heading')}")
    if summary_file.get("latest_attention_severity_counts"):
        print(
            "cycle_summary_latest_attention_severity_counts="
            f"{summary_file.get('latest_attention_severity_counts')}"
        )
    print(f"can_start={away_work.get('can_start')}")
    print(f"away_plan_present={away_work.get('plan_present')}")
    if away_work.get("expires_at_local"):
        print(f"expires_at_local={away_work.get('expires_at_local')}")
    print(f"away_report_ok={away_report.get('ok')}")
    print(f"away_report_pre_web_readiness_included={away_report.get('pre_web_readiness_included', False)}")
    for action in away_report.get("pre_web_next_actions", []):
        if str(action).strip():
            print(f"away_report_pre_web_next_action={action}")
    if away_report.get("resume_recommended_next_action"):
        print(f"away_report_resume_recommended_next_action={away_report.get('resume_recommended_next_action')}")
    print(f"ready_for_unattended_continuation={away_report.get('ready_for_unattended_continuation')}")
    print(f"attention_count={away_report.get('attention_count')}")
    print(f"needs_approval_count={away_report.get('needs_approval_count')}")
    entry = payload.get("entry", {}) if isinstance(payload.get("entry"), dict) else {}
    publication = (
        entry.get("publication_policy", {})
        if isinstance(entry.get("publication_policy"), dict)
        else {}
    )
    print(f"publication_skipped_count={entry.get('publication_skipped_count', 0)}")
    print(f"publication_requires_fresh_approval_count={publication.get('requires_fresh_approval_count', 0)}")
    print(f"publication_preapproved_but_blocked_count={publication.get('preapproved_but_blocked_count', 0)}")
    print(f"latest_backup_snapshot_id={latest.get('backup_snapshot_id', '')}")
    print(f"latest_project_snapshot_id={latest.get('project_snapshot_id', '')}")
    print(f"latest_metadata_snapshot_id={latest.get('metadata_snapshot_id', '')}")
    for item in payload.get("recent_cycles", []):
        if not isinstance(item, dict):
            continue
        snapshot_id = str(item.get("project_snapshot_id") or item.get("latest_project_snapshot_id") or "")
        print(
            "recent_cycle "
            f"cycle_id={item.get('cycle_id', '')} "
            f"decision={item.get('decision', '')} "
            f"created_at={item.get('created_at_local', '')} "
            f"publication_skipped_count={item.get('publication_skipped_count', 0)} "
            f"snapshot={snapshot_id}"
        )
    return exit_code


