    print(f"artifact_pointer_count={payload.get('artifact_pointer_count', 0)}")
    print(f"branch_policy={payload['branch_policy']}")
    for item in payload.get("branch_checkpoints", []):
        print(
            "branch_checkpoint "
            f"repo_id={item.get('repo_id')} "
            f"status={item.get('status')} "
            f"branch={item.get('branch')} "
            f"commit={item.get('commit', '')}"
        )
    print(f"restore_verification_requested={bool(restore_verification.get('requested'))}")
    if restore_verification.get("requested"):
        readiness = restore_readiness
        smoke = readiness.get("restore_smoke", {}) if isinstance(readiness.get("restore_smoke"), dict) else {}
        print(f"restore_readiness_ok={readiness.get('ok')}")
        print(f"restore_non_destructive_ready={readiness.get('ready_for_non_destructive_restore_review')}")
        print(f"restore_backup_ok={readiness.get('backup_ok')}")
        print(
            f"restore_smoke_status={smoke.get('status', '')} "
            f"executed={smoke.get('executed')} failed_count={smoke.get('failed_count')}"
        )
        for blocker in readiness.get("blockers", []):
            print(f"restore_blocker={blocker}")
        for warning in readiness.get("warnings", []):
            print(f"restore_warning={warning}")
    print(f"checkpoint_gate_ok={checkpoint_gate.get('ok')}")
    print(f"checkpoint_gate_blocker_count={checkpoint_gate.get('blocker_count', 0)}")
    print(f"checkpoint_branch_ref_blocking_count={checkpoint_gate.get('branch_ref_blocking_count', 0)}")
    print(f"checkpoint_logged={payload.get('checkpoint_logged', False)}")
    if payload.get("checkpoint_log_path"):
        print(f"checkpoint_log_path={payload.get('checkpoint_log_path')}")
    for blocker in checkpoint_gate.get("blockers", []):
        print(f"checkpoint_blocker={blocker}")
    for warning in checkpoint_gate.get("warnings", []):
        print(f"checkpoint_warning={warning}")
    print(f"checkpoint_policy={payload['checkpoint_policy']}")
    return 0 if payload.get("ok") else 1


