    print(f"snapshot_id={payload['snapshot_id']}")
    print(f"backup_snapshot_id={payload['backup_snapshot_id']}")
    checkpoint = payload.get("checkpoint", {}) if isinstance(payload.get("checkpoint"), dict) else {}
    print(f"checkpoint_branch_policy={checkpoint.get('branch_policy', '')}")
    for item in checkpoint.get("branch_checkpoints", []):
        if not isinstance(item, dict):
            continue
        print(
            "branch_checkpoint "
            f"repo_id={item.get('repo_id')} "
            f"status={item.get('status')} "
            f"branch={item.get('branch')} "
            f"commit={item.get('commit', '')}"
        )
    promotion = (
        payload.get("metadata_promotion", {})
        if isinstance(payload.get("metadata_promotion"), dict)
        else {}
    )
