    print(f"status={payload['status']}")
    print(f"ok={payload['ok']}")
    print(f"ready={payload['ready']}")
    print(f"blocking_step_count={payload['blocking_step_count']}")
    print(f"warning_step_count={payload['warning_step_count']}")
    summary = payload.get("summary", {}) if isinstance(payload.get("summary"), dict) else {}
    if "target_machine_required_count" in summary:
        print(f"target_machine_required_count={summary.get('target_machine_required_count')}")
    print(f"operator_summary={payload['operator_summary']}")
    for step in payload["steps"]:
        print(
            f"step id={step['id']} ok={step['ok']} status={step['status']} "
            f"blocking={step['blocking']} summary={step['summary']}"
        )
        if step.get("next_action"):
            print(f"step_next_action {step['id']}={step['next_action']}")
    for action in payload["next_actions"]:
        print(f"next_action={action}")
    if payload.get("confirmation_required"):
        return 2
    return 0 if payload.get("ok") else 1


