def cmd_project_backup_verify(args: argparse.Namespace) -> int:
    try:
        payload = build_project_backup_verify_payload(
            ops_root=Path(args.ops_root).expanduser(),
            project_name=args.project,
            snapshot_id=args.snapshot_id,
            backups_root=Path(args.backups_root).expanduser(),
            restore_root=Path(args.restore_root).expanduser(),
            restore_smoke=bool(args.restore_smoke),
            restore_wip=bool(args.restore_wip),
            replace_restore_workspace=bool(args.replace_restore_workspace),
            yes=bool(args.yes),
        )
    except RuntimeError as exc:
        if not args.json:
            raise
        payload = {
            "schema": "clutch.project_backup_verify.v1",
            "project_id": args.project,
            "snapshot_id": args.snapshot_id,
            "ok": False,
            "failed_check_count": 1,
            "error": str(exc),
            "repo_count": 0,
            "restorable_repo_count": 0,
            "file_count": 0,
            "repo_checks": [],
            "file_checks": [],
            "restore_smoke": {
                "requested": bool(args.restore_smoke),
                "executed": False,
                "confirmation_required": False,
                "status": "failed",
                "failed_count": 1,
                "repo_results": [],
                "warnings": [str(exc)],
            },
        }
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 1
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
    else:
        print(f"project_id={payload['project_id']}")
        print(f"snapshot_id={payload['snapshot_id']}")
        print(f"snapshot_root={payload['snapshot_root']}")
        print(f"ok={payload['ok']}")
        print(f"failed_check_count={payload['failed_check_count']}")
        print(f"repo_count={payload['repo_count']}")
        print(f"restorable_repo_count={payload['restorable_repo_count']}")
        print(f"file_count={payload['file_count']}")
        print(f"restore_workspace={payload['restore_workspace']}")
        for item in payload["repo_checks"]:
            print(
                "repo "
                f"repo_id={item['repo_id']} "
                f"status={item['status']} "
                f"bundle_verified={item['bundle_verified']} "
                f"restorable={item['restorable']} "
                f"head={item['head']}"
            )
        for item in payload["file_checks"]:
            if item["status"] != "ok":
                print(f"file path={item['path']} status={item['status']} snapshot_path={item['snapshot_path']}")
        smoke = payload.get("restore_smoke", {})
        if isinstance(smoke, dict) and smoke.get("requested"):
            print(
                "restore_smoke "
                f"status={smoke.get('status')} "
                f"executed={smoke.get('executed')} "
                f"restore_wip={smoke.get('restore_wip')} "
                f"failed_count={smoke.get('failed_count')} "
                f"restore_workspace={smoke.get('restore_workspace')}"
            )
            for warning in smoke.get("warnings", []):
                print(f"restore_smoke_warning={warning}")
            for item in smoke.get("repo_results", []):
                print(
                    "restore_smoke_repo "
                    f"repo_id={item.get('repo_id')} "
                    f"status={item.get('status')} "
                    f"head_matches_recorded={item.get('head_matches_recorded')} "
                    f"restored_head={item.get('restored_head')}"
                )
    smoke = payload.get("restore_smoke", {})
    if isinstance(smoke, dict) and smoke.get("confirmation_required"):
        return 2
    return 0 if payload["ok"] else 1


def cmd_project_restore_readiness(args: argparse.Namespace) -> int:
    try:
        payload = build_project_restore_readiness_payload(
            ops_root=Path(args.ops_root).expanduser(),
            project_name=args.project,
            machine_id_arg=args.machine_id,
            snapshot_id=args.snapshot_id,
            snapshots_root_arg=args.snapshots_root,
            repo_id_filter=args.repo_id,
            metadata_branch=args.metadata_branch,
            metadata_branch_prefix=args.metadata_branch_prefix,
            metadata_subdir=args.metadata_subdir,
            backup_snapshot_id=args.backup_snapshot_id,
            backups_root=Path(args.backups_root).expanduser(),
            restore_root=Path(args.restore_root).expanduser(),
            restore_smoke=bool(args.restore_smoke),
            restore_wip=bool(args.restore_wip),
            replace_restore_workspace=bool(args.replace_restore_workspace),
            yes=bool(args.yes),
        )
    except RuntimeError as exc:
        if not args.json:
            raise
        payload = {
            "schema": "clutch.project_restore_readiness.v1",
            "project_id": args.project,
            "machine_id": args.machine_id,
            "ok": False,
            "ready_for_non_destructive_restore_review": False,
            "ready_for_in_place_restore": False,
            "blockers": [str(exc)],
            "warnings": [],
            "next_actions": [],
        }
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
        return 1
    if args.json:
        print(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True))
    else:
        metadata = payload.get("metadata_restore_plan", {})
        local_snapshot = payload.get("machine_local_snapshot_restore_plan", {})
        backup = payload.get("backup_verify", {})
        smoke = payload.get("restore_smoke", {})
        print(f"project_id={payload['project_id']}")
        print(f"machine_id={payload['machine_id']}")
        print(f"ok={payload['ok']}")
        print(f"ready_for_non_destructive_restore_review={payload['ready_for_non_destructive_restore_review']}")
        print(f"ready_for_in_place_restore={payload['ready_for_in_place_restore']}")
        print(
            "metadata_restore_plan "
            f"available={metadata.get('available')} "
            f"snapshot_id={metadata.get('snapshot_id')} "
            f"metadata_commit={metadata.get('metadata_commit_short')}"
        )
        print(
            "machine_local_snapshot_restore_plan "
            f"available={local_snapshot.get('available')} "
            f"snapshot_id={local_snapshot.get('snapshot_id')}"
        )
        print(
            "backup_verify "
            f"available={backup.get('available')} "
            f"ok={backup.get('ok')} "
            f"snapshot_id={backup.get('snapshot_id')} "
            f"restorable_repo_count={backup.get('restorable_repo_count')}"
        )
        if isinstance(smoke, dict) and smoke:
            print(
                "restore_smoke "
                f"requested={smoke.get('requested')} "
                f"executed={smoke.get('executed')} "
                f"status={smoke.get('status')} "
                f"restore_workspace={smoke.get('restore_workspace')}"
            )
        for blocker in payload.get("blockers", []):
            print(f"blocker={blocker}")
        for warning in payload.get("warnings", []):
            print(f"warning={warning}")
        for action in payload.get("next_actions", []):
            print(f"next_action={action}")
    smoke = payload.get("restore_smoke", {})
    if isinstance(smoke, dict) and smoke.get("confirmation_required"):
        return 2
    return 0 if payload["ok"] else 1


