def cmd_project_online_backup(args: argparse.Namespace) -> int:
    ops_root = Path(args.ops_root).expanduser()
    payload = load_registry_payload(ops_root, "projects.json")
    payload_before = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    projects = payload.get("projects", [])
    if not isinstance(projects, list):
        raise RuntimeError("projects registry is malformed")

    project_query = str(args.project or "").strip().lower()
    repo_query = slugify(args.repo_id, "") if args.repo_id else ""
    matched_project: dict[str, Any] | None = None
    matched_repos: list[dict[str, Any]] = []

    for item in projects:
        if not isinstance(item, dict):
            continue
        project_id = str(item.get("project_id") or "")
        display_name = str(item.get("display_name") or "")
        if project_id.lower() != project_query and display_name.strip().lower() != project_query:
            continue
        matched_project = item
        repo_sources = item.get("repo_sources", [])
        if not isinstance(repo_sources, list):
            break
        for repo_source in repo_sources:
            if not isinstance(repo_source, dict):
                continue
            if repo_query and slugify(str(repo_source.get("repo_id") or ""), "") != repo_query:
                continue
            matched_repos.append(repo_source)
        break

    if matched_project is None:
        raise RuntimeError(f"project not found: {args.project}")
    if not matched_repos:
        if repo_query:
            raise RuntimeError(f"repo source not found: {args.repo_id}")
        raise RuntimeError(f"project has no repo sources: {args.project}")

    mutating = any(
        [
            args.online_remote_url is not None,
            args.online_remote_name is not None,
            args.online_branch is not None,
            args.require_approval,
            args.approve,
            args.revoke,
        ]
    )
    if args.approve and args.revoke:
        raise RuntimeError("--approve and --revoke cannot be used together")
    if mutating and not repo_query:
        raise RuntimeError("--repo-id is required when changing online backup settings")

    confirmation_required = bool(mutating and not args.yes and not args.dry_run)
    if mutating:
        selected_repo = matched_repos[0]
        if args.online_remote_url is not None:
            selected_repo["online_remote_url"] = args.online_remote_url
        if args.online_remote_name is not None:
            selected_repo["online_remote_name"] = args.online_remote_name
        if args.online_branch is not None:
            selected_repo["online_branch"] = args.online_branch

        enablement = online_enablement_state(selected_repo)
        if args.require_approval:
            enablement["required"] = True
        if args.revoke:
            enablement["required"] = True
            enablement["approved"] = False
            enablement["approved_by"] = ""
            enablement["approved_at_local"] = ""
            enablement["approval_note"] = args.approval_note
        if args.approve:
            if not str(selected_repo.get("online_remote_url") or "").strip():
                raise RuntimeError("cannot approve online backup before an online remote URL is configured")
            enablement["required"] = True
            enablement["approved"] = True
            enablement["approved_by"] = args.approver or os.environ.get("USER", "")
            enablement["approved_at_local"] = current_local_timestamp()
            enablement["approval_note"] = args.approval_note
        selected_repo["online_enablement"] = enablement

    payload_after = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    changed = payload_after != payload_before
    saved = False
    if changed and not args.dry_run and not confirmation_required:
        payload["last_updated_kst"] = current_local_timestamp()
        save_registry_payload(ops_root, "projects.json", payload)
        saved = True

    project_id = str(matched_project.get("project_id") or "")
    items = [online_backup_status(repo_source) for repo_source in matched_repos]
    result = {
        "schema": "clutch.project_online_backup.v1",
        "project_id": project_id,
        "dry_run": bool(args.dry_run),
        "changed": bool(changed),
        "saved": saved,
        "confirmation_required": confirmation_required,
        "repo_count": len(items),
        "repos": items,
    }
    if confirmation_required:
        result["confirmation_command_hint"] = (
            "rerun the same command with --yes after verifying the online remote and approval intent"
        )

    if args.json:
        print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
        return 2 if confirmation_required else 0

    print(f"project_id={result['project_id']}")
    print(f"dry_run={result['dry_run']}")
    print(f"changed={result['changed']}")
    print(f"saved={result['saved']}")
    print(f"confirmation_required={result['confirmation_required']}")
    for item in items:
        print(
            "repo "
            f"repo_id={item['repo_id']} "
            f"status={item['status']} "
            f"online_remote_url={item['online_remote_url']} "
            f"approved={item['approved']} "
            f"approved_by={item['approved_by']}"
        )
    if confirmation_required:
        print("confirmation_command_hint=rerun the same command with --yes after verifying the approval intent")
        return 2
    return 0


