def cmd_configure_project_repo(args: argparse.Namespace) -> int:
    ops_root = Path(args.ops_root).expanduser()
    payload = load_registry_payload(ops_root, "projects.json")
    payload_before = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    projects = payload.get("projects", [])
    if not isinstance(projects, list):
        raise RuntimeError("projects registry is malformed")

    target_project = project_entry(ops_root, args.project)
    if target_project is None:
        raise RuntimeError(f"project not found: {args.project}")
    project_id = str(target_project.get("project_id") or "")

    selected_project: dict[str, Any] | None = None
    selected_repo: dict[str, Any] | None = None
    repo_query = slugify(args.repo_id, "")

    for item in projects:
        if not isinstance(item, dict):
            continue
        if str(item.get("project_id") or "") != project_id:
            continue
        repo_sources = item.get("repo_sources", [])
        if not isinstance(repo_sources, list):
            continue
        for repo_source in repo_sources:
            if not isinstance(repo_source, dict):
                continue
            if slugify(str(repo_source.get("repo_id") or ""), "") != repo_query:
                continue
            selected_project = item
            selected_repo = repo_source
            break
        if selected_repo is not None:
            break

    if selected_project is None or selected_repo is None:
        raise RuntimeError(f"repo source not found: {args.repo_id}")

    if args.remote_url is not None:
        selected_repo["remote_url"] = args.remote_url
    if args.branch is not None:
        selected_repo["branch"] = args.branch
    if args.remote_name is not None:
        selected_repo["remote_name"] = args.remote_name
    if args.online_remote_url is not None:
        selected_repo["online_remote_url"] = args.online_remote_url
    if args.online_branch is not None:
        selected_repo["online_branch"] = args.online_branch
    if args.online_remote_name is not None:
        selected_repo["online_remote_name"] = args.online_remote_name

    enablement = remote_enablement_state(selected_repo)
    if args.require_approval is not None:
        enablement["required"] = args.require_approval
        if not args.require_approval:
            enablement["approved"] = False
            enablement["approved_by"] = ""
            enablement["approved_at_local"] = ""
            enablement["approval_note"] = ""
    if args.revoke_approval:
        enablement["approved"] = False
        enablement["approved_by"] = ""
        enablement["approved_at_local"] = ""
        enablement["approval_note"] = ""
    if args.approve_enable:
        if not str(selected_repo.get("remote_url") or "").strip() and not args.remote_url:
            raise RuntimeError("cannot approve remote enablement before a remote URL is configured")
        enablement["required"] = True
        enablement["approved"] = True
        enablement["approved_by"] = args.approver or os.environ.get("USER", "")
        enablement["approved_at_local"] = current_local_timestamp()
        enablement["approval_note"] = args.approval_note
    selected_repo["remote_enablement"] = enablement

    online_enablement = online_enablement_state(selected_repo)
    if args.require_online_approval is not None:
        online_enablement["required"] = args.require_online_approval
        if not args.require_online_approval:
            online_enablement["approved"] = False
            online_enablement["approved_by"] = ""
            online_enablement["approved_at_local"] = ""
            online_enablement["approval_note"] = ""
    if args.revoke_online_approval:
        online_enablement["approved"] = False
        online_enablement["approved_by"] = ""
        online_enablement["approved_at_local"] = ""
        online_enablement["approval_note"] = ""
    if args.approve_online_enable:
        if not str(selected_repo.get("online_remote_url") or "").strip() and not args.online_remote_url:
            raise RuntimeError("cannot approve online enablement before an online remote URL is configured")
        online_enablement["required"] = True
        online_enablement["approved"] = True
        online_enablement["approved_by"] = args.approver or os.environ.get("USER", "")
        online_enablement["approved_at_local"] = current_local_timestamp()
        online_enablement["approval_note"] = args.approval_note
    selected_repo["online_enablement"] = online_enablement

    payload_after = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    if payload_after != payload_before:
        payload["last_updated_kst"] = current_local_timestamp()
        save_registry_payload(ops_root, "projects.json", payload)

    result = {
        "schema": "clutch.project_repo_config.v1",
        "project_id": project_id,
        "repo_id": selected_repo.get("repo_id"),
        "remote_url": selected_repo.get("remote_url") or "",
        "remote_name": selected_repo.get("remote_name") or "origin",
        "branch": selected_repo.get("branch") or "main",
        "remote_enablement": enablement,
        "online_remote_url": selected_repo.get("online_remote_url") or "",
        "online_remote_name": selected_repo.get("online_remote_name") or "origin",
        "online_branch": selected_repo.get("online_branch") or selected_repo.get("branch") or "main",
        "online_enablement": online_enablement,
    }
    if args.json:
        print(json.dumps(result, ensure_ascii=False, indent=2, sort_keys=True))
        return 0
    print(f"project_id={result['project_id']}")
    print(f"repo_id={result['repo_id']}")
    print(f"remote_url={result['remote_url']}")
    print(f"remote_name={result['remote_name']}")
    print(f"branch={result['branch']}")
    print(f"remote_approval_required={result['remote_enablement']['required']}")
    print(f"remote_approved={result['remote_enablement']['approved']}")
    print(f"approved_by={result['remote_enablement']['approved_by']}")
    print(f"online_remote_url={result['online_remote_url']}")
    print(f"online_remote_name={result['online_remote_name']}")
    print(f"online_branch={result['online_branch']}")
    print(f"online_approval_required={result['online_enablement']['required']}")
    print(f"online_approved={result['online_enablement']['approved']}")
    print(f"online_approved_by={result['online_enablement']['approved_by']}")
    return 0


