    if args.command == "notify-status":
        if args.json:
            print(json.dumps(notify_status_payload(), ensure_ascii=False, indent=2, sort_keys=True))
            return 0
        return notify_cmd(["status"])
    if args.command == "notify-mode-on":
        argv = ["mode-on"]
        if args.thread_id:
            argv.extend(["--thread-id", args.thread_id])
        return notify_cmd(argv)
    if args.command == "notify-mode-off":
        argv = ["mode-off"]
        if args.thread_id:
            argv.extend(["--thread-id", args.thread_id])
        return notify_cmd(argv)
    if args.command == "notify-mode-long":
        argv = ["mode-long", "--minutes", str(args.minutes)]
        if args.thread_id:
            argv.extend(["--thread-id", args.thread_id])
        return notify_cmd(argv)
    if args.command == "notify-send-test":
        argv = ["send-test"]
        if args.thread_id:
            argv.extend(["--thread-id", args.thread_id])
        if args.message:
            argv.extend(["--message", args.message])
        return notify_cmd(argv)
    if args.command == "notify-send-message":
        return notify_cmd(["send-message", "--title", args.title, "--message", args.message])
    if args.command == "notify-configure":
        argv = ["configure"]
        if args.enabled is not None:
            argv.append("--enabled" if args.enabled else "--no-enabled")
        if args.topic is not None:
            argv.extend(["--topic", args.topic])
        if args.server_url is not None:
            argv.extend(["--server-url", args.server_url])
        if args.title is not None:
            argv.extend(["--title", args.title])
        if args.machine_label is not None:
            argv.extend(["--machine-label", args.machine_label])
        if args.message_template is not None:
            argv.extend(["--message-template", args.message_template])
        if args.default_session_mode is not None:
            argv.extend(["--default-session-mode", args.default_session_mode])
        if args.default_session_threshold_minutes:
            argv.extend(["--default-session-threshold-minutes", str(args.default_session_threshold_minutes)])
        if args.collab_completed_threshold_minutes >= 0:
            argv.extend(["--collab-completed-threshold-minutes", str(args.collab_completed_threshold_minutes)])
        return notify_cmd(argv)
    if args.command == "admin-status":
        return cmd_admin_status(args)
